export function createEventEmitter() {
  const listeners: Record<string, Array<{
    callback: (...args: any[]) => any;
    once: boolean;
  }>> = {};

  return {
    on: function (event: string, callback: (...args: any[]) => any) {
      if (!listeners[event]) {
        listeners[event] = [];
      }
      listeners[event].push({ callback, once: false });
    },
    once: function (event: string, callback: (...args: any[]) => any) {
      if (!listeners[event]) {
        listeners[event] = [];
      }
      listeners[event].push({ callback, once: true });
    },
    off: function (event: string, callback: (...args: any[]) => any) {
      if (!listeners[event]) return;
      const index = listeners[event].findIndex(
        (listener) => listener.callback === callback
      );
      if (index !== -1) {
        listeners[event].splice(index, 1);
      }
    },
    emit: function (event: string, ...args: any[]) {
      if (!listeners[event]) return [];
      const eventListeners = [...listeners[event]];
      const results: any[] = [];
      for (const listener of eventListeners) {
        results.push(listener.callback(...args));
        if (listener.once) {
          this.off(event, listener.callback);
        }
      }
      return results;
    },
  };
}
