export function createEventEmitter(): EventEmitter {
  type Listener = (payload: unknown) => unknown;
  interface EventEmitter { 
    on(event: string, listener: Listener): number;
    once(event: string, listener: Listener): number;
    off(event: string, listener: Listener): boolean;
    emit(event: string, payload: unknown): unknown[];
    listenerCount(event: string): number;
  }

  const listeners: Record<string, { listener: Listener, once: boolean }[]> = {};

  return {
    on(event: string, listener: Listener): number {
      if (!listeners[event]) {
        listeners[event] = [];
      }
      listeners[event].push({ listener, once: false });
      return listeners[event].length;
    },
    once(event: string, listener: Listener): number {
      if (!listeners[event]) {
        listeners[event] = [];
      }
      listeners[event].push({ listener, once: true });
      return listeners[event].length;
    },
    off(event: string, listener: Listener): boolean {
      if (!listeners[event]) {
        return false;
      }
      const index = listeners[event].findIndex(l => l.listener === listener);
      if (index === -1) {
        return false;
      }
      listeners[event].splice(index, 1);
      return true;
    },
    emit(event: string, payload: unknown): unknown[] {
      const eventListeners = listeners[event];
      if (!eventListeners) {
        return [];
      }
      const results: unknown[] = [];
      for (let i = 0; i < eventListeners.length; i++) {
        const { listener, once } = eventListeners[i];
        results.push(listener(payload));
        if (once) {
          eventListeners.splice(i, 1);
          i--;
        }
      }
      return results;
    },
    listenerCount(event: string): number {
      return listeners[event]?.length ?? 0;
    }
  };
}
