export function createRateLimiter() {
  const windows = new Map<string, number[]>();

  return {
    request(key: string, nowMs: number) {
      const currentWindow = Math.floor(nowMs / 1000);
      const keyWindows = windows.get(key) || [];

      const recent = keyWindows.filter(t => t >= currentWindow - 1);
      if (recent.length >= 3) {
        return { allowed: false, retryAfter: null };
      }

      keyWindows.push(currentWindow);
      windows.set(key, keyWindows);
      return { allowed: true, retryAfter: null };
    },
    reset(key: string) {
      windows.set(key, []);
    },
  };
}
