interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

type Bucket = { count: number; windowStart: number }

export function createRateLimiter(): RateLimiter {
  const buckets = new Map<string, Bucket>()

  return {
    allow(key: string, nowMs: number): boolean {
      const bucket = buckets.get(key) ?? { count: 0, windowStart: -Infinity }
      const { count, windowStart } = bucket
      const windowEnd = windowStart + 1000
      const shouldReset = nowMs - windowStart >= 1000

      if (shouldReset) {
        bucket.count = 0
        bucket.windowStart = nowMs
        buckets.set(key, bucket)
        return true
      }

      const canAllow = count < 3
      if (canAllow) {
        bucket.count += 1
        buckets.set(key, bucket)
      }
      return canAllow
    },
    remaining(key: string, nowMs: number): number {
      const bucket = buckets.get(key) ?? { count: 0, windowStart: -Infinity }
      const { count, windowStart } = bucket
      const shouldReset = nowMs - windowStart >= 1000
      return shouldReset ? 3 : 3 - count
    },
    reset(key: string): void {
      buckets.delete(key)
    },
  }
}
