```typescript
type Listener = {
  fn: (...args: unknown[]) => unknown;
  once: boolean;
};

type EventEmitter = {
  on: (event: string, listener: (...args: unknown[]) => void) => void;
  once: (event: string, listener: (...args: unknown[]) => void) => void;
  off: (event: string, listener: (...args: unknown[]) => void) => void;
  emit: (event: string, ...args: unknown[]) => unknown[];
};

const createEventEmitter = (): EventEmitter => {
  const listeners = new Map<string, Listener[]>();

  const add = (
    event: string,
    listener: (...args: unknown[]) => void,
    once: boolean
  ): void => {
    const eventListeners = listeners.get(event) ?? [];
    eventListeners.push({ fn: listener, once });
    listeners.set(event, eventListeners);
  };

  const off = (
    event: string,
    listener: (...args: unknown[]) => void
  ): void => {
    const eventListeners = listeners.get(event);
    if (!eventListeners) return;

    const index = eventListeners.findIndex((l) => l.fn === listener);
    if (index !== -1) {
      eventListeners.splice(index, 1);
    }
  };

  return {
    on: (event, listener) => add(event, listener, false),
    once: (event, listener) => add(event, listener, true),
    off,
    emit: (event, ...args) => {
      const eventListeners = listeners.get(event);
      if (!eventListeners || eventListeners.length === 0) {
        return [];
      }

      const results: unknown[] = [];
      const newListeners: Listener[] = [];

      for (const l of eventListeners) {
        const result = l.fn(...args);
        results.push(result);

        if (!l.once) {
          newListeners.push(l);
        }
      }

      listeners.set(event, newListeners);
      return results;
    },
  };
};

export { createEventEmitter };
