```typescript
type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ fn: Listener; once: boolean }>>();

  const eventEmitter: EventEmitter = {
    on(event, listener) {
      const list = listeners.get(event) ?? [];
      list.push({ fn: listener, once: false });
      listeners.set(event, list);
      return list.length;
    },

    once(event, listener) {
      const list = listeners.get(event) ?? [];
      list.push({ fn: listener, once: true });
      listeners.set(event, list);
      return list.length;
    },

    off(event, listener) {
      const list = listeners.get(event);
      if (!list) return false;

      const index = list.findIndex(item => item.fn === listener);
      if (index === -1) return false;

      list.splice(index, 1);
      return true;
    },

    emit(event, payload) {
      const list = listeners.get(event);
      if (!list) return [];

      const results: unknown[] = [];
      const indicesToRemove: number[] = [];

      for (let i = 0; i < list.length; i++) {
        const item = list[i];
        const returnVal = item.fn(payload);
        results.push(returnVal);

        if (item.once) {
          indicesToRemove.push(i);
        }
      }

      // Remove 'once' listeners in reverse order to keep valid indices
      for (let i = indicesToRemove.length - 1; i >= 0; i--) {
        list.splice(indicesToRemove[i], 1);
      }

      return results;
    },

    listenerCount(event) {
      return listeners.get(event)?.length ?? 0;
    },
  };

  return eventEmitter;
}
