export function createRateLimiter() {
  const storage = new Map<string, { timestamp: number; count: number }>();
  const WINDOW_MS = 1000;
  const MAX_REQUESTS = 3;

  return {
    acquire(key: string, nowMs: number): boolean {
      const record = storage.get(key);
      // If the key doesn't exist or the window has fully elapsed (or passed),
      // start a fresh window with 1 request.
      if (!record || nowMs - record.timestamp >= WINDOW_MS) {
        storage.set(key, { timestamp: nowMs, count: 1 });
        return true;
      }

      // If within the window and under the limit, increment counter.
      if (record.count < MAX_REQUESTS) {
        record.count += 1;
        return true;
      }

      // Limit reached.
      return false;
    },

    reset(key: string): void {
      storage.delete(key);
    },
  };
}
