  value: unknown;
  expiresAt: number;
}

export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const store = new Map<string, CacheEntry>();

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void {
      store.set(key, {
        value,
        expiresAt: nowMs + ttlMs,
      });
    },
    get(key: string, nowMs: number): unknown {
      const entry = store.get(key);
      if (!entry || entry.expiresAt <= nowMs) {
        return undefined;
      }
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const entry = store.get(key);
      if (!entry) return false;
      return entry.expiresAt > nowMs;
    },
    delete(key: string): boolean {
      return store.delete(key);
    },
    size(nowMs: number): number {
      let count = 0;
      for (const entry of store.values()) {
        if (entry.expiresAt > nowMs) {
          count++;
        }
      }
      return count;
    },
    clear(): void {
      store.clear();
    },
  };
}
