interface Calculator {
  add(n: number): Calculator
  subtract(n: number): Calculator
  multiply(n: number): Calculator
  divide(n: number): Calculator
  clear(): Calculator
  result(): number
  memoryStore(): Calculator
  memoryRecall(): number
  memoryClear(): Calculator
  memoryAdd(): Calculator
}

class CalculatorImpl {
  private currentValue: number = 0
  private memory: number = 0

  add(n: number): this {
    this.currentValue += n
    return this
  }

  subtract(n: number): this {
    this.currentValue -= n
    return this
  }

  multiply(n: number): this {
    this.currentValue *= n
    return this
  }

  divide(n: number): this {
    if (n === 0) {
      throw new Error('Cannot divide by zero')
    }
    this.currentValue /= n
    return this
  }

  clear(): this {
    this.currentValue = 0
    return this
  }

  result(): number {
    return this.currentValue
  }

  memoryStore(): this {
    this.memory = this.currentValue
    return this
  }

  memoryRecall(): number {
    return this.memory
  }

  memoryClear(): this {
    this.memory = 0
    return this
  }

  memoryAdd(): this {
    this.memory += this.currentValue
    return this
  }
}

export function createCalculator(): Calculator {
  return new CalculatorImpl() as Calculator
}
