function createEventEmitter() {
  const events: Record<string, Array<{ listener: (...args: unknown[]) => unknown; once: boolean }>> = {};

  return {
    on(event: string, listener: (...args: unknown[]) => unknown) {
      if (!events[event]) {
        events[event] = [];
      }
      events[event].push({ listener, once: false });
      const off = () => {
        const index = events[event]?.findIndex(l => l.listener === listener && l.once === false);
        if (index !== undefined && index !== -1) {
          events[event]!.splice(index, 1);
        }
      };
      return { off };
    },

    once(event: string, listener: (...args: unknown[]) => unknown) {
      if (!events[event]) {
        events[event] = [];
      }
      events[event].push({ listener, once: true });
      const off = () => {
        const index = events[event]?.findIndex(l => l.listener === listener && l.once === true);
        if (index !== undefined && index !== -1) {
          events[event]!.splice(index, 1);
        }
      };
      return { off };
    },

    off(event: string, listener: (...args: unknown[]) => unknown) {
      const index = events[event]?.findIndex(l => l.listener === listener);
      if (index !== undefined && index !== -1) {
        events[event]!.splice(index, 1);
      }
    },

    emit<U extends unknown[]>(event: string, ...args: U): unknown[] {
      const listeners = [...(events[event] || [])];
      const results: unknown[] = [];

      for (const { listener, once } of listeners) {
        const result = listener(...args);
        results.push(result);
      }

      const remainingListeners = listeners.filter(({ once: listenerOnce }) => !listenerOnce);
      events[event] = remainingListeners;

      return results;
    },
  };
}

export { createEventEmitter };
