export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const cache = new Map<string, unknown>()
  const expires = new Map<string, number>()

  return {
    set(key, value, nowMs, ttlMs = 1000) {
      const expiresAt = nowMs + ttlMs
      cache.set(key, value)
      expires.set(key, expiresAt)
    },

    get(key, nowMs) {
      const exp = expires.get(key)
      if (exp === undefined || nowMs >= exp) {
        return undefined
      }
      return cache.get(key)
    },

    has(key, nowMs) {
      const exp = expires.get(key)
      return exp !== undefined && nowMs < exp
    },

    delete(key) {
      const existed = cache.has(key)
      cache.delete(key)
      expires.delete(key)
      return existed
    },

    size(nowMs) {
      let count = 0
      for (const [key, exp] of expires.entries()) {
        if (nowMs < exp) {
          count++
        } else {
          cache.delete(key)
        }
      }
      return count
    },

    clear() {
      cache.clear()
      expires.clear()
    }
  }
}
