export function createRateLimiter(): RateLimiter {
  const keyStore = new Map<string, number[]>()

  function tryAcquire(key: string, nowMs: number): boolean {
    let timestamps = keyStore.get(key)
    if (!timestamps) {
      timestamps = []
      keyStore.set(key, timestamps)
    }

    const windowStart = nowMs - 1000

    const validTimestamps = timestamps.filter(ts => ts > windowStart)
    if (validTimestamps.length < 3) {
      timestamps.push(nowMs)
      return true
    }

    return false
  }

  function reset(key: string): void {
    keyStore.delete(key)
  }

  return {
    tryAcquire,
    reset
  }
}
