export function createRateLimiter(): RateLimiter {
  const keyStates = new Map<string, { count: number; windowStart: number }>()
  const limit = 3
  const windowMs = 1000

  const allow = (key: string, nowMs: number): boolean => {
    const record = keyStates.get(key)

    if (!record || nowMs - record.windowStart >= windowMs) {
      keyStates.set(key, { count: 1, windowStart: nowMs })
      return true
    }

    return record.count < limit
  }

  const remaining = (key: string, nowMs: number): number => {
    const record = keyStates.get(key)
    if (!record || nowMs - record.windowStart >= windowMs) {
      return limit
    }
    return Math.max(0, limit - record.count)
  }

  const reset = (key: string): void => {
    keyStates.delete(key)
  }

  return {
    allow,
    remaining,
    reset
  }
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}
