export function createEventEmitter() {
    type Listener = (...args: any[]) => any;
    type ListenerEntry = { fn: Listener; once: boolean };

    const events = new Map<string, ListenerEntry[]>();

    function on(eventName: string, fn: Listener): void {
        const list = events.get(eventName) ?? [];
        list.push({ fn, once: false });
        events.set(eventName, list);
    }

    function once(eventName: string, fn: Listener): void {
        const list = events.get(eventName) ?? [];
        list.push({ fn, once: true });
        events.set(eventName, list);
    }

    function off(eventName: string, fn: Listener): void {
        const list = events.get(eventName);
        if (!list) return;
        const index = list.findIndex(entry => entry.fn === fn);
        if (index !== -1) {
            list.splice(index, 1);
            if (list.length === 0) events.delete(eventName);
        }
    }

    function emit(eventName: string, ...args: any[]): any[] {
        const list = events.get(eventName);
        if (!list) return [];
        const results: any[] = [];
        const toCall = [...list];
        for (const entry of toCall) {
            const res = entry.fn(...args);
            results.push(res);
            if (entry.once) {
                const idx = list.indexOf(entry);
                if (idx !== -1) list.splice(idx, 1);
            }
        }
        if (list.length === 0) events.delete(eventName);
        return results;
    }

    return { on, once, off, emit };
