export interface RateLimiter {
  allow(key: string, nowMs: number): boolean
  remaining(key: string, nowMs: number): number
  reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
  const limit = 3
  const windowMs = 1000
  const state = new Map<
    string,
    { windowStart: number; count: number }
  >()

  const cleanWindow = (key: string, nowMs: number) => {
    const entry = state.get(key)
    if (!entry) return
    if (nowMs - entry.windowStart >= windowMs) {
      entry.windowStart = nowMs
      entry.count = 0
    }
  }

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = state.get(key) ?? {
        windowStart: nowMs,
        count: 0,
      }
      state.set(key, entry)
      cleanWindow(key, nowMs)
      if (entry.count < limit) {
        entry.count += 1
        return true
      }
      return false
    },

    remaining(key: string, nowMs: number): number {
      const entry = state.get(key)
      if (!entry) return limit
      cleanWindow(key, nowMs)
      const rem = limit - entry.count
      return rem > 0 ? rem : 0
    },

    reset(key: string): void {
      state.delete(key)
    },
  }
}
