    has(key, nowMs) {
      const entry = map.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        map.delete(key);
        return false;
      }
      return true;
    },

    delete(key) {
      return map.delete(key);
    },

    size(nowMs) {
      purge(nowMs);
      return map.size;
    },

    clear() {
      map.clear();
