export type EventListener = (...args: any[]) => any;

export interface EventEmitter {
  on(event: string, listener: EventListener): void;
  once(event: string, listener: EventListener): void;
  off(event: string, listener: EventListener): void;
  emit(event: string, ...args: any[]): any[];
}

export function createEventEmitter(): EventEmitter {
  const events = new Map<
    string,
    Array<{ listener: EventListener; once: boolean }>
  >();

  return {
    on(event, listener) {
      if (!events.has(event)) events.set(event, []);
      events.get(event)!.push({ listener, once: false });
    },

    once(event, listener) {
      if (!events.has(event)) events.set(event, []);
      events.get(event)!.push({ listener, once: true });
    },

    off(event, listener) {
      const list = events.get(event);
      if (!list) return;
      const idx = list.findIndex(
        (entry) => entry.listener === listener && !entry.once
      );
      if (idx >= 0) {
        list.splice(idx, 1);
      } else {
        // If not found as normal, try to remove once listener as well
        const idxOnce = list.findIndex(
          (entry) => entry.listener === listener
        );
        if (idxOnce >= 0) {
          list.splice(idxOnce, 1);
        }
      }
      if (list.length === 0) events.delete(event);
    },

    emit(event, ...args) {
      const list = events.get(event);
      if (!list) return [];
      const results: any[] = [];
      // Copy to avoid issues if listeners modify list during emit
      for (const entry of [...list]) {
        results.push(entry.listener(...args));
        if (entry.once) {
          const idx = list.indexOf(entry);
          if (idx >= 0) list.splice(idx, 1);
        }
      }
      if (list.length === 0) events.delete(event);
      return results;
    },
  };
}

export type Listener = (payload: unknown) => unknown;

export interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<
    string,
    Array<{ listener: Listener; once: boolean }>
  >();

  return {
    on(event, listener) {
      const arr = listeners.get(event) ?? [];
      arr.push({ listener, once: false });
      listeners.set(event, arr);
      return arr.length;
    },

    once(event, listener) {
      const arr = listeners.get(event) ?? [];
      arr.push({ listener, once: true });
      listeners.set(event, arr);
      return arr.length;
    },

    off(event, listener) {
      const arr = listeners.get(event);
      if (!arr) return false;
      const idx = arr.findIndex((l) => l.listener === listener);
      if (idx === -1) return false;
      arr.splice(idx, 1);
      if (arr.length === 0) listeners.delete(event);
      else listeners.set(event, arr);
      return true;
    },

    emit(event, payload) {
      const arr = listeners.get(event);
      if (!arr) return [];
      const results: unknown[] = [];
      const retained: Array<{ listener: Listener; once: boolean }> = [];
      for (const { listener, once } of arr) {
        results.push(listener(payload));
        if (!once) retained.push({ listener, once });
      }
      if (retained.length > 0) listeners.set(event, retained);
      else listeners.delete(event);
      return results;
    },

    listenerCount(event) {
      const arr = listeners.get(event);
      return arr ? arr.length : 0;
    },
  };
}

export function createRateLimiter() {
  const windowMs = 1000;
  const maxRequests = 3;
  const state = new Map<string, { start: number; count: number }>();

  function allow(key: string, nowMs: number): boolean {
    const keyState = state.get(key);
    if (!keyState) {
      state.set(key, { start: nowMs, count: 1 });
      return true;
    }
    if (nowMs - keyState.start >= windowMs) {
      // Window has fully elapsed
      keyState.start = nowMs;
      keyState.count = 1;
      return true;
    }
    if (keyState.count < maxRequests) {
      keyState.count += 1;
      return true;
    }
    return false;
  }

  function reset(key: string): void {
    state.delete(key);
  }

  return { allow, reset };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const state = new Map<string, { start: number; count: number }>();

  function ensureState(key: string, nowMs: number) {
    let entry = state.get(key);
    if (!entry) {
      entry = { start: nowMs, count: 0 };
      state.set(key, entry);
      return entry;
    }
    if (nowMs - entry.start >= windowMs) {
      entry.start = nowMs;
      entry.count = 0;
    }
    return entry;
  }

  return {
    allow(key, nowMs) {
      const entry = ensureState(key, nowMs);
      if (entry.count < limit) {
        entry.count += 1;
        return true;
      }
      return false;
    },
    remaining(key, nowMs) {
      const entry = ensureState(key, nowMs);
      return Math.max(0, limit - entry.count);
    },
    reset(key) {
      state.delete(key);
    },
  };
}

