export function createTtlCache() {
  const map = new Map<string, { value: unknown; expiresAt: number }>();
  const DEFAULT_TTL_MS = 1000;

  const api = {
    set(
      key: string,
      value: unknown,
      nowMs: number,
      ttlMs: number = DEFAULT_TTL_MS
    ): void {
      map.set(key, { value, expiresAt: nowMs + ttlMs });
    },

    get(key: string, nowMs: number): unknown {
      const entry = map.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        map.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = map.get(key);
      if (!entry) return false;
      if (nowMs >= entry.expiresAt) {
        map.delete(key);
        return false;
      }
      return true;
    },

    delete(key: string): boolean {
      return map.delete(key);
    },

    size(nowMs: number): number {
      let count = 0;
      const keysToDelete: string[] = [];
      for (const [key, entry] of map.entries()) {
        if (nowMs >= entry.expiresAt) {
          keysToDelete.push(key);
        } else {
          count++;
        }
      }
      for (const key of keysToDelete) {
        map.delete(key);
      }
      return count;
    },

    clear(): void {
      map.clear();
    },
  };

  return api;
}

