export function createCalculator(): {
    add: (num: number) => void;
    subtract: (num: number) => void;
    multiply: (num: number) => void;
    divide: (num: number) => void;
    clear: () => void;
    result: () => number;
    memoryStore: () => void;
    memoryAdd: () => number;
    memoryClear: () => void;
    memoryRecall: () => [number, number];
} {
    let currentValue = 0;
    let memoryValue = 0;

    return {
        add(num: number): void {
            currentValue = num + currentValue;
        },
        subtract(num: number): void {
            currentValue -= num;
        },
        multiply(num: number): void {
            currentValue *= num;
        },
        divide(num: number): void {
            currentValue /= num;
        },
        clear(): void {
            currentValue = 0;
        },
        result(): number {
            return currentValue;
        },
        memoryStore(): void {
            memoryValue = currentValue;
        },
        memoryAdd(): number {
            memoryValue += currentValue;
            return memoryValue;
        },
        memoryClear(): void {
            memoryValue = 0;
        },
        memoryRecall(): [number, number] {
            const result = [...memoryValue];
            currentValue = 0;
            return result;
        }
    };
