function createRateLimiter(nowMs: number) {
  const limitPerWindow = 3;
  const windowMs = 1000;

  const rates: { [key: string]: { lastRequestMs?: number; requestsInWindow?: number } } = {};

  return function (key: string): { limitReached: boolean; remainingRequests: number } {
    if (!rates[key]) {
      rates[key] = { lastRequestMs: nowMs, requestsInWindow: 0 };
    }

    const nowForKey = rates[key].lastRequestMs + windowMs;
    const inCurrentWindow = nowMs < nowForKey;

    let limitReached = false;
    if (inCurrentWindow) {
      const remainingRequests = Math.min(limitPerWindow - rates[key].requestsInWindow, 0);
      rates[key].requestsInWindow += remainingRequests;
      rates[key].lastRequestMs = nowMs;
      limitReached = remainingRequests === 0;
    } else {
      delete rates[key];
      rates[key] = { lastRequestMs: nowMs, requestsInWindow: 0 };
    }

    return { limitReached, remainingRequests };
  };

  function reset(key: string) {
    delete rates[key];
    rates[key] = { lastRequestMs: undefined, requestsInWindow: 0 };
  }
}

