export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
} {
  const cache: { [key: string]: { value: unknown; expiresAt: number } | undefined } = {};
  let lastRefreshTime = Date.now() + 1;

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const newExpiresAt =
        ttlMs === undefined ? nowMs + 1000 : nowMs + ttlMs;
      if (cache[key] && cache[key].expiresAt <= lastRefreshTime) {
        cache[key].value = value;
        cache[key].expiresAt = newExpiresAt;
      } else {
        cache[key] = { value, expiresAt: newExpiresAt };
      }
      lastRefreshTime = Math.max(lastRefreshTime, nowMs + 1);
    },

    get(key: string, nowMs: number): unknown {
      const cachedValue = cache[key];
      if (cachedValue && cachedValue.expiresAt <= nowMs) {
        delete cache[key];
        return undefined;
      }
      return cachedValue?.value ?? undefined;
    },

    has(key: string, nowMs: number): boolean {
      return Object.prototype.hasOwnProperty.call(cache, key);
    },

    delete(key: string): boolean {
      if (Object.prototype.hasOwnProperty.call(cache, key)) {
        delete cache[key];
        return true;
      }
      return false;
    },

    size(nowMs: number): number {
      let count = 0;
      for (const k in cache) {
        const v = cache[k];
        if (
          v &&
          v.expiresAt <= nowMs &&
          v.value !== undefined
        ) {
          ++count;
        }
      }
      return count;
    },

    clear(): void {
      Object.keys(cache).forEach((k) => delete cache[k]);
      lastRefreshTime = -1;
    },
  };
}
