  const getMemoryClearResult = () => {
    memoryValue = 0;
    return [memoryValue, 0];
  };

  const addToListMemory = (v: number) => {
    memoryValue += v;
    return this;
  };

  const getMemoryStore = () => memoryValue;

  const result = currentValue;

  const memoryRecall = () => memoryValue;

  return { add, subtract, multiply, divide, clearMemory, getMemoryClearResult, addToListMemory, getMemoryStore, result, memoryRecall };
