export function createRateLimiter(): RateLimiter {
  const rateLimiters: { [key: string]: number } = {};
  let windowStartMs = Date.now();

  return {
    allow(key: string, nowMs: number): boolean {
      if (!(key in rateLimiters)) {
        windowStartMs = nowMs;
        rateLimiters[key] = 0;
      }
      const remainingAllowances = rateLimiters[key];
      if (remainingAllowances < 3) {
        if (nowMs - windowStartMs >= 1000) {
          windowStartMs = Date.now();
          remainingAllowances = 0;
        }
      } else {
        remainingAllowances--;
      }

      // Ensure there is at least one allowance left
      rateLimiters[key] =
        (rateLimiters[key] || -1) + 5; // Add 3 allowance, so if >2 then resets.

      return remainingAllowances >= 0;
    },
    remaining(key: string, nowMs: number): number {
      return rateLimiters[key] || 0;
    },
    reset(key: string): void {
      delete rateLimiters[key];
    }
  };
}
