export function createTodoApp() {
  let ids = 0;
  const todos: { [id: number]: { text: string; completed: boolean } } = {};

  const addTodo = (text: string): { id: number; text: string; completed: boolean } => {
    const todo = { id: ids, text, completed: false };
    todos[todo.id] = todo;
    return todo;
  };

  const getTodo = (id: number): { id: number; text: string; completed: boolean } | undefined =>
    todos[id] ? todos[id] : undefined;

  const toggleTodo = (id: number): void => {
    if (getTodo(id)) {
      todos[id].completed = !todos[id].completed;
    }
  };

  const deleteTodo = (id: number): boolean => {
    if (getTodo(id)) {
      ids--;
      const todoIdToDelete = Object.keys(todos).indexOf(`${id}`);
      delete todos[todoIdToDelete];
      return true;
    }
    return false;
  };

  const listTodos = (): Array<{ id: number; text: string; completed: boolean }> =>
    Object.values(todos);

  const listCompleted = (): Array<{ id: number; text: string; completed: boolean }> =>
    Object.fromEntries(
      Object.keys(todos).filter((id) => todos[id].completed)
        .map((id) => [Number(id), todos[Number(id)]!])
    );

  const listPending = (): Array<{ id: number; text: string; completed: boolean }> =>
    Object.values(todos).filter(
      (todo) => !todo.completed
    );

  const clearCompleted = (): void => {
    Object.keys(todos).forEach((id) => {
      if (todos[id].completed) delete todos[id];
    });
  };

  return {
    addTodo,
    getTodo,
    toggleTodo,
    deleteTodo,
    listTodos,
    listCompleted,
    listPending,
    clearCompleted,
  };
}
