  subtract(n: number): Calculator;
  multiply(n: number): Calculator;
  divide(n: number): Calculator;
  clear(): Calculator;
  result(): number;
  memoryStore(): Calculator;
  memoryRecall(): number;
  memoryClear(): Calculator;
  memoryAdd(): Calculator;
}

export function createCalculator(): Calculator {
  let currentValue = 0;
  let memoryValue = 0;

  const calculator: Calculator = {
    add(n: number): Calculator {
      currentValue += n;
      return calculator;
    },
    subtract(n: number): Calculator {
      currentValue -= n;
      return calculator;
    },
    multiply(n: number): Calculator {
      currentValue *= n;
      return calculator;
    },
    divide(n: number): Calculator {
      if (n === 0) throw new Error("Division by zero");
      currentValue /= n;
      return calculator;
    },
    clear(): Calculator {
      currentValue = 0;
      return calculator;
    },
    result(): number {
      return currentValue;
    },
    memoryStore(): Calculator {
      memoryValue = currentValue;
      return calculator;
    },
    memoryRecall(): number {
      return memoryValue;
    },
    memoryClear(): Calculator {
      memoryValue = 0;
      return calculator;
    },
    memoryAdd(): Calculator {
      memoryValue += currentValue;
      return calculator;
    },
  };

  return calculator;
}
