type Listener<T extends any[] = any[]> = (...args: T) => any;
type OneTimeListener<T extends any[] = any[]> = (this: void, ...args: T) => any;

interface EventEmitter<T extends Record<string, any[]>> {
    on<K extends keyof T>(event: K, listener: Listener<T[K]>): void;
    once<K extends keyof T>(event: K, listener: OneTimeListener<T[K]>): void;
    off<K extends keyof T>(event: K, listener: Listener<T[K]>): void;
    emit<K extends keyof T>(event: K, ...args: T[K]): ReturnType<Listener<T[K>>>[];
}

function createEventEmitter<T extends Record<string, any[]>>(): EventEmitter<T> {
    const listeners = new Map<string, { listener: Listener; isOneTime: boolean }[]>();

    return {
        on<K extends keyof T>(event: K, listener: Listener<T[K]>) {
            const eventKey = event as string;
            if (!listeners.has(eventKey)) {
                listeners.set(eventKey, []);
            }
            listeners.get(eventKey)!.push({ listener, isOneTime: false });
        },
        once<K extends keyof T>(event: K, listener: OneTimeListener<T[K]>) {
            const eventKey = event as string;
            if (!listeners.has(eventKey)) {
                listeners.set(eventKey, []);
            }
            listeners.get(eventKey)!.push({ listener, isOneTime: true });
        },
        off<K extends keyof T>(event: K, listener: Listener<T[K]>) {
            const eventKey = event as string;
            const eventListeners = listeners.get(eventKey);
            if (!eventListeners) return;

            for (let i = eventListeners.length - 1; i >= 0; i--) {
                if (eventListeners[i].listener === listener && !eventListeners[i].isOneTime) {
                    eventListeners.splice(i, 1);
                }
            }
        },
        emit<K extends keyof T>(event: K, ...args: T[K]): ReturnType<Listener<T[K]>>[] {
            const eventKey = event as string;
            const eventListeners = listeners.get(eventKey) || [];
            const results: any[] = [];

            for (let i = 0; i < eventListeners.length; i++) {
                const { listener, isOneTime } = eventListeners[i];
                results.push(listener(...args));

                if (isOneTime) {
                    eventListeners.splice(i, 1);
                    i--;
                }
            }

            return results;
        }
    };
}
