function createRateLimiter(): RateLimiter {
    const state = new Map<string, { count: number; windowStart: number }>();

    return {
        allow(key: string, nowMs: number): boolean {
            const entry = state.get(key);
            if (!entry) {
                state.set(key, { count: 1, windowStart: nowMs });
                return true;
            }

            const elapsed = nowMs - entry.windowStart;
            if (elapsed >= 1000) {
                state.set(key, { count: 1, windowStart: nowMs });
                return true;
            }

            if (entry.count < 3) {
                state.set(key, { count: entry.count + 1, windowStart: entry.windowStart });
                return true;
            }

            return false;
        },
        reset(key: string): void {
            state.delete(key);
        }
    };
}
