export function createRateLimiter(): RateLimiter {
    const state: Record<string, { count: number; windowStart: number }> = {};

    return {
        allow(key: string, nowMs: number): boolean {
            const entry = state[key] || { count: 0, windowStart: nowMs };
            const windowExpired = nowMs - entry.windowStart >= 1000;

            if (windowExpired) {
                state[key] = { count: 1, windowStart: nowMs };
                return true;
            }

            if (entry.count < 3) {
                state[key] = { ...entry, count: entry.count + 1 };
                return true;
            }

            return false;
        },

        remaining(key: string, nowMs: number): number {
            const entry = state[key];
            if (!entry) return 3;

            const windowExpired = nowMs - entry.windowStart >= 1000;
            if (windowExpired) {
                return 3;
            }

            return 3 - entry.count;
        },

        reset(key: string): void {
            delete state[key];
        }
    };
}

interface RateLimiter {
    allow(key: string, nowMs: number): boolean;
    remaining(key: string, nowMs: number): number;
    reset(key: string): void;
}
