export function createTtlCache() {
    const cache: Map<string, { value: unknown; expiresAt: number }> = new Map();

    return {
        set(key: string, value: unknown, nowMs: number, ttlMs = 1000): void {
            const expiresAt = nowMs + ttlMs;
            cache.set(key, { value, expiresAt });
        },
        get(key: string, nowMs: number): unknown {
            const entry = cache.get(key);
            return entry?.expiresAt >= nowMs ? entry.value : undefined;
        },
        has(key: string, nowMs: number): boolean {
            const entry = cache.get(key);
            return entry !== undefined && entry.expiresAt >= nowMs;
        },
        delete(key: string): boolean {
            return cache.delete(key);
        },
        size(nowMs: number): number {
            return Array.from(cache.values()).filter(entry => entry.expiresAt >= nowMs).length;
        },
        clear(): void {
            cache.clear();
        }
    };
}
