export type Listener<T = void> = (payload?: T) => void | Promise<void>;

interface ListenerHandle<T = void> {
  type: 'normal' | 'once';
  listener: Listener<T>;
}

type EventMap = Record<string, ListenerHandle<any>[] | never>;

export function createEventEmitter<TEvents extends Record<string, any>>(): {
  on: <K extends keyof TEvents>(event: K, listener: Listener<TEvents[K]>) => () => void;
  once: <K extends keyof TEvents>(event: K, listener: Listener<TEvents[K]>) => () => void;
  off: <K extends keyof TEvents>(event: K, listener: Listener<TEvents[K]>) => void;
  emit: <K extends keyof TEvents>(event: K, payload?: TEvents[K]) => ReturnType<TEvents[K]>[];
} {
  const listeners = {} as EventMap;

  const normalizeEventName = <K extends keyof TEvents>(event: K) => event.toString();

  function registerListener<K extends keyof TEvents>(
    event: K,
    listener: Listener<TEvents[K]>,
    type: 'normal' | 'once'
  ) {
    const eventName = normalizeEventName(event);
    if (!listeners[eventName]) {
      listeners[eventName] = [];
    }

    const handle: ListenerHandle<TEvents[K]> = { type, listener };
    listeners[eventName].push(handle);
    return () => {
      listeners[eventName] = listeners[eventName].filter(l => l !== handle);
    };
  }

  function removeListener<K extends keyof TEvents>(
    event: K,
    listener: Listener<TEvents[K]>
  ) {
    const eventName = normalizeEventName(event);
    listeners[eventName] = listeners[eventName].filter(
      (l: any) => l.listener !== listener
    );
  }

  return {
    on: (event, listener: Listener) => registerListener(event, listener, 'normal'),
    once: (event, listener: Listener) => registerListener(event, listener, 'once'),
    off: (event, listener: Listener) => removeListener(event, listener),
    emit: async <K extends keyof TEvents>(event: K, payload?: TEvents[K]) => {
      const eventName = normalizeEventName(event);
      if (!listeners[eventName]) return [];

      const returnValues: Array<ReturnType<Listener<TEvents[K]>>> = [];
      for (const { listener, type } of listeners[eventName]) {
        const result = listener(payload);
        if (type === 'once') {
          removeListener(event, listener);
        }
        if (result instanceof Promise) {
          await result;
        }
        returnValues.push(result as any);
      }
      return returnValues;
    }
  };
}
