export function createTtlCache() {
  interface CacheEntry<T = unknown> {
    value: T;
    expiresAt: number;
  }

  const cacheMap = new Map<string, CacheEntry>();

  const defaultTtlMs = 1000;

  return {
    set<T>(key: string, value: T, nowMs: number, ttlMs: number = defaultTtlMs): void {
      const expiresAt = nowMs + ttlMs;
      cacheMap.set(key, { value, expiresAt });
    },

    get(key: string, nowMs: number): unknown {
      const entry = cacheMap.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) {
        cacheMap.delete(key);
        return undefined;
      }
      return entry.value;
    },

    has(key: string, nowMs: number): boolean {
      const entry = cacheMap.get(key);
      return entry !== undefined && nowMs < entry.expiresAt;
    },

    delete(key: string): boolean {
      return cacheMap.delete(key);
    },

    size(nowMs: number): number {
      return [...cacheMap.values()].filter(entry => nowMs < entry.expiresAt).length;
    },

    clear(): void {
      cacheMap.clear();
    }
  };
}
