type Listener<TArgs extends unknown[] = unknown[]> = (...args: TArgs) => unknown;
type EventHandlersMap = Map<string, Listener<unknown[]>[]>;
type ListenerKey = { id: symbol; isOnce?: boolean };

interface EventEmitter {
  on<TArgs extends unknown[]>(
    eventName: string,
    listener: Listener<TArgs>
  ): () => void;
  once<TArgs extends unknown[]>(
    eventName: string,
    listener: Listener<TArgs>
  ): ListenerKey;
  off(key: ListenerKey | symbol): boolean;
  emit<TArgs extends unknown[]>(
    eventName: string,
    ...args: TArgs
  ): unknown[];
}

export function createEventEmitter(): EventEmitter {
  const handlers: EventHandlersMap = new Map();
  let nextId = 0;

  function emit<TArgs extends unknown[]>(
    eventName: string,
    ...args: TArgs
  ): unknown[] {
    const results: unknown[] = [];
    const currentHandlers = handlers.get(eventName)?.slice() || [];

    for (const { listener, isOnce } of currentHandlers) {
      if (isOnce) {
        currentHandlers.splice(currentHandlers.indexOf({ listener, isOnce }), 1);
      }
      results.push(listener(...args));
    }
    return results;
  }

  function on<TArgs extends unknown[]>(
    eventName: string,
    listener: Listener<TArgs>
  ): () => void {
    const key = Symbol();
    const listeners = handlers.get(eventName) || new Map();
    listeners.set(key, { listener, isOnce: false });
    handlers.set(eventName, [...(handlers.get(eventName) || []), { listener, isOnce: false }]);
    return () => off(key);
  }

  function once<TArgs extends unknown[]>(
    eventName: string,
    listener: Listener<TArgs>
  ): ListenerKey {
    const id = Symbol(nextId++);
    const listeners = handlers.get(eventName) || new Map();
    const key: ListenerKey = { id, isOnce: true };
    handlers.set(eventName, [...(handlers.get(eventName) || []), { listener, isOnce: true }]);
    return key;
  }

  function off(key: ListenerKey | symbol): boolean {
    const keySymbol = typeof key === 'symbol' ? key : key.id;
    for (const [eventName, listeners] of handlers) {
      const filteredListeners = listeners.filter(
        ({ listener }) => Symbol.toString(keySymbol) !== Symbol.toString(keySymbol)
      );
      if (filteredListeners.length < listeners.length) {
        handlers.set(eventName, filteredListeners);
        return true;
      }
      handlers.delete(eventName);
    }
    return false;
  }

  return { on, once, off, emit };
}
