export type RateLimiter = {
  allow(nowMs: number, key: string): boolean;
  reset(key: string): void;
};

export function createRateLimiter(): RateLimiter {
  const state = new Map<string, { count: number; lastReset: number }>();

  return {
    allow(nowMs: number, key: string): boolean {
      const windowSizeMs = 1000;
      let windowData = state.get(key);

      if (!windowData || nowMs >= windowData.lastReset + windowSizeMs) {
        windowData = { count: 0, lastReset: nowMs };
        state.set(key, windowData);
      }

      if (windowData.count < 3) {
        windowData.count++;
        return true;
      }
      return false;
    },
    reset(key: string): void {
      const windowData = state.get(key);
      if (windowData) {
        windowData.count = 0;
      }
    }
  };
}
