interface RateLimiter {
    allow(key: string, nowMs: number): boolean
    remaining(key: string, nowMs: number): number
    reset(key: string): void
}

export function createRateLimiter(): RateLimiter {
    const limit = 3;
    const windowMs = 1000;
    const state = new Map<string, { count: number; windowStart: number; }>();

    return {
        allow(key: string, nowMs: number): boolean {
            const entry = state.get(key) || { count: 0, windowStart: -Infinity };
            const isNewWindow = nowMs - entry.windowStart >= windowMs;

            if (isNewWindow) {
                state.set(key, { count: 1, windowStart: nowMs });
                return true;
            }

            if (entry.count < limit) {
                state.set(key, { count: entry.count + 1, windowStart: entry.windowStart });
                return true;
            }

            return false;
        },

        remaining(key: string, nowMs: number): number {
            const entry = state.get(key);
            if (!entry) return limit;

            const isNewWindow = nowMs - entry.windowStart >= windowMs;
            if (isNewWindow) {
                state.set(key, { count: 0, windowStart: nowMs });
                return limit;
            }

