export function createTodoApp() {
    let nextId = 1;
    const todos = new Map<number, { id: number, text: string, completed: boolean }>();

    const addTodo = (text: string) => {
        const todo = { id: nextId, text, completed: false } as const;
        todos.set(nextId, todo);
        nextId++;
        return todo;
    };

    const getTodo = (id: number) => todos.get(id);

    const toggleTodo = (id: number) => {
        const todo = todos.get(id);
        if (todo) {
            todo.completed = !todo.completed;
            todos.set(id, todo);
        }
    };

    const deleteTodo = (id: number): boolean => {
        return todos.delete(id);
    };

    const listTodos = () => Array.from(todos.values());

    const listCompleted = () => Array.from(todos.values()).filter(todo => todo.completed);

    const listPending = () => Array.from(todos.values()).filter(todo => !todo.completed);

    const clearCompleted = () => {
        let completedFound = false;
        Array.from(todos.entries()).forEach(([id, todo]) => {
            if (todo.completed) {
                todos.delete(id);
                completedFound = true;
            }
        });
    };

    return {
        addTodo,
        getTodo,
        toggleTodo,
        deleteTodo,
        listTodos,
        listCompleted,
        listPending,
        clearCompleted,
    };
}
