export function createTodoApp(): TodoApp {
    let nextId = 1;
    const todos: Todo[] = [];

    return {
        addTodo(text) {
            const todo: Todo = { id: nextId, text, completed: false };
            todos.push(todo);
            nextId++;
            return todo;
        },
        getTodo(id) {
            return todos.find(todo => todo.id === id);
        },
        toggleTodo(id) {
            const todo = todos.find(todo => todo.id === id);
            if (!todo) return;
            todo.completed = !todo.completed;
        },
        deleteTodo(id) {
            const initialLength = todos.length;
            todos.splice(todos.findIndex(todo => todo.id === id), 1);
            return todos.length !== initialLength;
        },
        listTodos() {
            return [...todos];
        },
        listCompleted() {
            return todos.filter(todo => todo.completed);
        },
        listPending() {
            return todos.filter(todo => !todo.completed);
        },
        clearCompleted() {
            todos.splice(
                todos.findIndex(todo => !todo.completed),
                todos.length - todos.findIndex(todo => !todo.completed)
            );
        }
    };
}

interface Todo {
    id: number;
    text: string;
    completed: boolean;
}

interface TodoApp {
    addTodo(text: string): Todo;
    getTodo(id: number): Todo | undefined;
    toggleTodo(id: number): void;
    deleteTodo(id: number): boolean;
    listTodos(): Todo[];
    listCompleted(): Todo[];
    listPending(): Todo[];
    clearCompleted(): void;
}
