interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}

export function createTtlCache(): TtlCache {
  const store: Record<string, { value: unknown; expiresAt: number }> = {};

  return {
    get(key: string, nowMs: number): unknown {
      const entry = store[key];
      if (!entry || entry.expiresAt <= nowMs) return undefined;
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const entry = store[key];
      return Boolean(entry && entry.expiresAt > nowMs);
    },
    set(key: string, value: unknown, nowMs: number, ttlMs = 1000): void {
      const expiresAt = nowMs + ttlMs;
      store[key] = { value, expiresAt };
    },
    delete(key: string): boolean {
      const hadKey = store.hasOwnProperty(key);
      delete store[key];
      return hadKey;
    },
    size(nowMs: number): number {
      return Object.values(store).filter(entry => entry.expiresAt > nowMs).length;
    },
    clear(): void {
      Object.keys(store).forEach(key => delete store[key]);
    }
  };
}
