export function createEventEmitter() {
    const listeners = new Map<string, Array<(value: any) => void>[]>();

    const emit = (eventName: string, ...args: any[]) => {
        const eventListeners = listeners.get(eventName) || [];
        const results: any[] = [];
        for (const listener of eventListeners) {
            const result = listener(args);
            if (result !== undefined) results.push(result);
        }
        return results;
    };

    const on = (eventName: string, listener: (value: any) => void) => {
        const existingListeners = listeners.get(eventName) || [];
        existingListeners.push(listener);
        listeners.set(eventName, existingListeners);
    };

    const once = (eventName: string, listener: (value: any) => void) => {
        const existingListeners = listeners.get(eventName) || [];
        existingListeners.push((...args: any[]) => {
            const result = listener(...args);
            listeners.delete(eventName);
            return result;
        });
        listeners.set(eventName, existingListeners);
    };

    const off = (eventName: string, listener: (value: any) => void) => {
        const existingListeners = listeners.get(eventName) || [];
        const filteredListeners = existingListeners.filter(l => l !== listener);
        listeners.set(eventName, filteredListeners);
    };

    return { emit, on, once, off };
}
