            perKey: new Map<string, { count: number; lastReset: number }>(),
        },
        rateLimitNow: (nowMs: number, key: string): boolean => {
            const entry = rateLimiter.rateLimit.perKey.get(key);
            if (!entry) {
                rateLimiter.rateLimit.perKey.set(key, { count: 0, lastReset: nowMs });
                return true;
            }

            const elapsed = nowMs - entry.lastReset;
            const windowSize = 1000;
            const windowStart = nowMs - (elapsed % windowSize);
            const windowCount = Math.floor(elapsed / windowSize);

            if (windowCount > 0) {
                entry.count = 0;
                entry.lastReset = nowMs - windowSize * windowCount;
            }

            if (entry.count < 3) {
                entry.count++;
                return true;
            }

            return false;
        },
        reset: (key: string) => {
            rateLimiter.rateLimit.perKey.delete(key);
        },
    };

    return rateLimiter;
