    return entry?.expiresAt > nowMs ?? false;
  }

  delete(key: string): boolean {
    return this.cache.delete(key);
  }

  size(nowMs: number): number {
    return Array.from(this.cache.values()).filter((entry) => entry.expiresAt > nowMs).length;
