export function createEventEmitter() {
  type Listener = (...args: any[]) => any;
  const listeners: Record<string, {fn: Listener, oneTime: boolean}[]> = {};

  function on(event: string, fn: Listener) {
    if (!listeners[event]) listeners[event] = [];
    listeners[event].push({fn, oneTime: false});
  }

  function once(event: string, fn: Listener) {
    if (!listeners[event]) listeners[event] = [];
    listeners[event].push({fn, oneTime: true});
  }

  function off(event: string, fn: Listener) {
    const arr = listeners[event];
    if (!arr) return;
    for (let i = 0; i < arr.length; i++) {
      if (arr[i].fn === fn) {
        arr.splice(i, 1);
        return;
      }
    }
  }

  function emit(event: string, ...args: any[]) {
    const arr = listeners[event];
    const returns: any[] = [];
    if (!arr) return returns;
    for (const entry of arr) {
      const ret = entry.fn(...args);
      returns.push(ret);
      if (entry.oneTime) {
        const idx = arr.indexOf(entry);
        if (idx !== -1) arr.splice(idx, 1);
      }
    }
    return returns;
  }

  return { on, once, off, emit };
}

