export function createRateLimiter(): RateLimiter {
  const LIMIT = 3;
  const WINDOW_MS = 1000;
  const state = new Map<string, { count: number; windowStart: number }>();

  function getEntry(key: string, nowMs: number) {
    let entry = state.get(key);
    if (!entry) {
      entry = { count: 0, windowStart: nowMs };
      state.set(key, entry);
    }
    if (nowMs - entry.windowStart >= WINDOW_MS) {
      entry.windowStart = nowMs;
      entry.count = 0;
    }
    return entry;
  }

  function resetKey(key: string) {
    state.delete(key);
  }

  return {
    allow(key, nowMs): boolean {
      const entry = getEntry(key, nowMs);
      if (entry.count < LIMIT) {
        entry.count += 1;
        return true;
      }
      return false;
    },
    remaining(key, nowMs): number {
      const entry = getEntry(key, nowMs);
      return Math.max(0, LIMIT - entry.count);
    },
    reset(key: string) {
      resetKey(key);
    },
  };
}
