        todos[idx].completed = !todos[idx].completed;
      }
    },
    deleteTodo(id: number): boolean {
      const idx = findIndex(id);
      if (idx === -1) return false;
      todos.splice(idx, 1);
      return true;
    },
    listTodos(): Todo[] {
      return [...todos];
    },
    listCompleted(): Todo[] {
      return todos.filter(t => t.completed);
    },
    listPending(): Todo[] {
      return todos.filter(t => !t.completed);
    },
    clearCompleted(): void {
      for (let i = todos.length - 1; i >= 0; i--) {
        if (todos[i].completed) {
          todos.splice(i, 1);
        }
      }
    },
  };
