export function createCalculator(): Calculator {
  class CalculatorImpl {
    private current: number;
    private memory: number;

    constructor() {
      this.current = 0;
      this.memory = 0;
    }

    add(n: number): this {
      this.current += n;
      return this;
    }

    subtract(n: number): this {
      this.current -= n;
      return this;
    }

    multiply(n: number): this {
      this.current *= n;
      return this;
    }

    divide(n: number): this {
      if (n !== 0) {
        this.current /= n;
      }
      return this;
    }

    clear(): this {
      this.current = 0;
      return this;
    }

    result(): number {
      return this.current;
    }

    memoryStore(): this {
      this.memory = this.current;
      return this;
    }

    memoryRecall(): number {
      return this.memory;
    }

    memoryClear(): this {
      this.memory = 0;
      return this;
    }

    memoryAdd(): this {
      this.memory += this.current;
      return this;
    }
  }

  return new CalculatorImpl();
}

type Listener = (...args: any[]) => any;

interface EventMap {
  [event: string]: Array<{ handler: Listener; once: boolean }>;
}

export function createEventEmitter() {
  const listeners: EventMap = {};

  function on(event: string, listener: Listener) {
    if (!listeners[event]) listeners[event] = [];
    listeners[event].push({ handler: listener, once: false });
  }

  function off(event: string, listener: Listener) {
    const arr = listeners[event];
    if (!arr) return;
    for (let i = 0; i < arr.length; i++) {
      if (arr[i].handler === listener) {
        arr.splice(i, 1);
        return;
      }
    }
  }

  function emit(event: string, ...args: any[]): any[] {
    const arr = listeners[event];
    if (!arr) return [];
    const returns: any[] = [];
    for (let i = 0; i < arr.length; i++) {
      const { handler, once } = arr[i];
      const ret = handler(...args);
      returns.push(ret);
      if (once) {
        arr.splice(i, 1);
        i--;
      }
    }
    return returns;
  }

  return { on, off, emit };
}

export function createEventEmitter() {
  const listeners: Record<string, ((payload: unknown) => unknown)[]> = {};

  const on = (event: string, listener: (payload: unknown) => unknown): number => {
    if (!listeners[event]) listeners[event] = [];
    listeners[event].push(listener);
    return listeners[event].length;
  };

  const once = (event: string, listener: (payload: unknown) => unknown): number => {
    const wrapper = (payload: unknown) => {
      const result = listener(payload);
      off(event, wrapper);
      return result;
    };
    return on(event, wrapper);
  };

  const off = (event: string, listener: (payload: unknown) => unknown): boolean => {
    const arr = listeners[event];
    if (!arr) return false;
    const idx = arr.indexOf(listener);
    if (idx !== -1) {
      arr.splice(idx, 1);
      return true;
    }
    return false;
  };

  const emit = (event: string, payload: unknown): unknown[] => {
    const arr = listeners[event];
    if (!arr) return [];
    const results = [];
    for (const l of arr) {
      results.push(l(payload));
    }
    return results;
  };

  const listenerCount = (event: string): number => {
    return (listeners[event] as any)?.length ?? 0;
  };

  return { on, once, off, emit, listenerCount };
}

