export function createRateLimiter() {
  const state = new Map<string, {count: number, start: number}>();
  function reset(key: string) {
    state.delete(key);
  }
  function allow(key: string, nowMs: number): boolean {
    const entry = state.get(key);
    const win = Math.floor(nowMs / 1000) * 1000;
    if (!entry) {
      state.set(key, {count: 1, start: win});
      return true;
    }
    if (entry.start !== win) {
      entry.count = 1;
      entry.start = win;
      return true;
    }
    if (entry.count < 3) {
      entry.count++;
      return true;
    }
    return false;
  }
  return { allow, reset };
}

