interface TtlCache {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
    get(key: string, nowMs: number): unknown;
    has(key: string, nowMs: number): boolean;
    delete(key: string): boolean;
    size(nowMs: number): number;
    clear(): void;
}
export function createTtlCache(): TtlCache {
    const store = new Map<string, {value: unknown; expiresAt: number}>();
    const defaultTTL = 1000;
    return {
        set(key, value, nowMs, ttlMs) {
            const expiresAt = ttlMs === 0 ? nowMs : nowMs + (ttlMs ?? defaultTTL);
            store.set(key, {value, expiresAt});
        },
        get(key, nowMs) {
            const entry = store.get(key);
            if (!entry) return undefined;
            if (nowMs >= entry.expiresAt) {
                store.delete(key);
                return undefined;
            }
            return entry.value;
        },
        has(key, nowMs) {
            const entry = store.get(key);
            return !!entry && nowMs < entry.expiresAt;
        },
        delete(key) {
            return store.delete(key);
        },
        size(nowMs) {
            let count = 0;
            for (const {expiresAt} of store.values()) {
                if (nowMs < expiresAt) count++;
            }
            return count;
        },
        clear() {
            store.clear();
        },
    };
}

