type Listener = (payload: unknown) => unknown;

class EventEmitter {
  private events: { [key: string]: { fn: Listener; once: boolean }[] } = {};

  on(event: string, listener: Listener): number {
    this.events[event] = this.events[event] || [];
    this.events[event].push({ fn: listener, once: false });
    return this.events[event].length;
  }

  once(event: string, listener: Listener): number {
    this.events[event] = this.events[event] || [];
    this.events[event].push({ fn: listener, once: true });
    return this.events[event].length;
  }

  off(event: string, listener: Listener): boolean {
    const list = this.events[event];
    if (!list) return false;
    for (let i = 0; i < list.length; i++) {
      if (list[i].fn === listener) {
        list.splice(i, 1);
        return true;
      }
    }
    return false;
  }

  emit(event: string, payload: unknown): unknown[] {
    const list = this.events[event] || [];
    const results: unknown[] = [];
    for (const item of list) {
      results.push(item.fn(payload));
    }
    if (this.events[event]) {
      this.events[event] = list.filter(item => !item.once);
    }
    return results;
  }

  listenerCount(event: string): number {
    return (this.events[event] || []).length;
  }
}

export function createEventEmitter(): EventEmitter {
  return new EventEmitter();
}
