export function createTtlCache(): TtlCache {
  const cache: Record<string, { value: unknown; expiresAt: number }> = {};

  return {
    set(key, value, nowMs, ttlMs = 1000) {
      if (ttlMs > 0) {
        cache[key] = { value, expiresAt: nowMs + ttlMs };
      } else {
        delete cache[key];
      }
    },
    get(key, nowMs) {
      const entry = cache[key];
      return entry && nowMs < entry.expiresAt ? entry.value : undefined;
    },
    has(key, nowMs) {
      const entry = cache[key];
      return Boolean(entry && nowMs < entry.expiresAt);
    },
    delete(key) {
      if (cache[key]) {
        delete cache[key];
        return true;
      }
      return false;
    },
    size(nowMs) {
      let count = 0;
      for (const key in cache) {
        const entry = cache[key];
        if (entry && nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear() {
      cache = {};
    },
  };
}
