import { EventEmitter } from 'events';

interface Listener {
  listener: (...args: any[]) => any;
  once?: boolean;
}

function createEventEmitter() {
  const ee = new EventEmitter();

  function addListener(eventName: string, listener: (...args: any[]) => any, once?: boolean): void {
    const listeners = ee.eventNames().includes(eventName) ? ee.listeners(eventName) : [];
    const isNewListener = listeners.every(l => l.listener !== listener);

    if (isNewListener) {
      ee.on(eventName, listener);
      ee.once && ee.removeListener(eventName, function wrapper(...args) {
        try {
          listener.apply(this, args);
        } finally {
          ee.off(eventName, wrapper);
        }
      });
    }

    const addedOnce = once ? ee.once(eventName, listener) : false;
    return { addedOnce };
  }

  function emit(eventName: string, ...args: any[]): (any | undefined)[] {
    const listeners = ee.listeners(eventName).slice();
    if (!listeners.length) return [];

    return listeners.map(l => l.listener.apply(ee, args));
  }

  function on(eventName: string, listener: (...args: any[]) => any): this {
    addListener(eventName, listener);
    return ee;
  }

  function once(eventName: string, listener: (...args: any) => any): this {
    addListener(eventName, listener, true);
    return ee;
  }

  function off(eventName: string, listener?: (...args: any[]) => any): this {
    if (listener && typeof listener === 'function') {
      ee.removeListener(eventName, listener);
    } else {
      ee.removeAllListeners(eventName);
    }
    return ee;
  }

  return { on, once, emit, off };
}

export { createEventEmitter };
