    max: 100,
    ttl: 1000,
    ttlResolution: 'now'
  });

  function set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void {
    const expiresAt = nowMs + ttlMs;
    cache.set(key, { value,expiresAt });
  }

  function get(key: string, nowMs: number): unknown {
    const entry = cache.get(key);
    return entry?.value;
  }

  function has(key: string, nowMs: number): boolean {
    const entry = cache.get(key);
    if (!entry) return false;
    return nowMs < entry.expiresAt;
  }

  function delete(key: string): boolean {
     const removedEntry = cache.delete(key);
      return removedEntry !== undefined ? true : false;
  }

  function size(nowMs: number): number {
        const liveEntriesCount = Object.values(cache.cache).filter(entry => nowMs < entry.expiresAt && !entry.deletionPending()).length;
        return liveEntriesCount;
    }

  function clear(): void {
        cache.reset();
  }

    return { set, get, has, delete, size, clear };
