export function createEventEmitter() {
  const listenerMap = new Map<string, ((payload: unknown) => unknown)[]>();

  function listenerList(event: string): ((payload: unknown) => unknown)[] {
    if (!listenerMap.has(event)) {
      listenerMap.set(event, []);
    }
    return listenerMap.get(event)!;
  }

  const ee = {
    on(event: string, listener: (payload: unknown) => unknown): number {
      let list = listenerList(event);
      list.push(listener);
      return list.length;
    },
    once(event: string, listener: (payload: unknown) => unknown): number {
      const singleListener = (...args: any[]) => {
        ee.off(event, singleListener);
        return listener(...args);
      };
      ee.on(event, singleListener);
      return ee.listenerCount(event);
    },
    off(event: string, listener: (payload: unknown) => unknown): boolean {
      let list = listenerList(event);
      return Boolean(list && list.splice(list.indexOf(listener), 1));
    },
    emit(event: string, payload: unknown): any[] {
      const ret: any[] = [];
      const list = ee.listenerCount(event) ? ee.on(event) : [];
      for (const fn of list.slice(0)) {
        ret.push(fn(payload));
      }
      return ret;
    },
    listenerCount(event: string): number {
      return listenerList(event).length;
    },
  };

  return ee as EventEmitter;
}

type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}
