import { Map } from "immutable";

interface RateLimiter {
  addRequest(key: string, nowMs: number): boolean;
  reset(key: string): void;
}

function createRateLimiter(): RateLimiter {
  const requests = new Map<string, Array<number>>();

  function addRequest(key: string, nowMs: number): boolean {
    const timestampWindow = Math.floor(nowMs / 1000);
    let keyData = requests.get(key) || [];
    let windowIndex = keyData.findIndex(ts => ts >= timestampWindow);

    if (windowIndex === -1 && keyData.length > 0) {
      windowIndex = 0;
      while (keyData[windowIndex] < timestampWindow - 1) {
        keyData.shift();
      }
    }

    if (windowIndex === -1 || nowMs - keyData[windowIndex] * 1000 <= 999) {
      keyData.push(nowMs);
      requests.set(key, keyData.slice(-3));
      return false;
    } else {
      keyData.unshift(nowMs);
      while (keyData.length > 3) {
        keyData.pop();
      }
      requests.set(key, keyData);
      return true;
    }
  }

  function reset(key: string): void {
    requests.delete(key);
  }

  const rateLimiter = { addRequest, reset };
  return rateLimiter as RateLimiter;
}
