export function createCalculator(): {
    result: () => number;
    add: (value: number) => createCalculator;
    subtract: (value: number) => createCalculator;
    multiply: (value: number) => createCalculator;
    divide: (value: number) => createCalculator;
    clear: () => createCalculator;
    memoryStore: () => createCalculator;
    memoryAdd: () => createCalculator;
    memoryClear: () => createCalculator;
    memoryRecall: () => number;
} {
    let currentValue = 0;
    let memoryValue = 0;

    return {
        result: () => currentValue,
        add: (value) => {
            currentValue += value;
            return this;
        },
        subtract: (value) => {
            currentValue -= value;
            return this;
        },
        multiply: (value) => {
            currentValue *= value;
            return this;
        },
        divide: (value) => {
            if (value !== 0) {
                currentValue /= value;
            }
            return this;
        },
        clear: () => {
            currentValue = 0;
            return this;
        },
        memoryStore: () => {
            memoryValue = currentValue;
            return this;
        },
        memoryAdd: () => {
            memoryValue += currentValue;
            return this;
        },
        memoryClear: () => {
            memoryValue = 0;
            return this;
        },
        memoryRecall: () => memoryValue
    };
}
