export function createEventEmitter(): {
    on: (event: string, listener: (...args: any[]) => any) => void;
    once: (event: string, listener: (...args: any[]) => any) => void;
    off: (event: string, listener: (...args: any[]) => any) => void;
    emit: (event: string, ...args: any[]) => any[];
} {
    const listeners = new Map<string, Array<[(...args: any[]) => any, boolean]>>();

    return {
        on(event: string, listener: (...args: any[]) => any): void {
            if (!listeners.has(event)) {
                listeners.set(event, []);
            }
            listeners.get(event)!.push([listener, false]);
        },
        once(event: string, listener: (...args: any[]) => any): void {
            const onceListener = (...args: any[]): any => {
                listener(...args);
                this.off(event, onceListener);
            };
            this.on(event, onceListener);
        },
        off(event: string, listener: (...args: any[]) => any): void {
            if (!listeners.has(event)) return;

            const eventListeners = listeners.get(event)!;
            for (let i = 0; i < eventListeners.length; i++) {
                if (eventListeners[i][0] === listener) {
                    eventListeners.splice(i, 1);
                    break;
                }
            }
        },
        emit(event: string, ...args: any[]): any[] {
            const eventListeners = listeners.get(event)!;
            const results: any[] = [];
            for (const [listener, once] of eventListeners) {
                results.push(listener(...args));
                if (once) this.off(event, listener);
            }
            return results;
        }
    };
}
