export function createRateLimiter(): RateLimiter {
  const limits: Map<string, number[]> = new Map();

  return {
    allow(key: string, nowMs: number): boolean {
      const windowStart = Math.floor(nowMs / 1000) * 1000;
      let quota = limits.get(key);
      if (!quota || quota.length === 0) {
        quota = [nowMs];
        limits.set(key, quota);
        return true;
      }

      while (quota[0] < windowStart) {
        quota.shift();
        if (quota.length === 0) {
          quota.push(nowMs);
          return true;
        }
      }

      if (quota.length < 3) {
        quota.push(nowMs);
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const windowStart = Math.floor(nowMs / 1000) * 1000;
      let quota = limits.get(key);
      if (!quota || quota.length === 0) {
        quota = [nowMs];
        limits.set(key, quota);
        return 3 - quota.length;
      }

      while (quota[0] < windowStart) {
        quota.shift();
        if (quota.length === 0) {
          quota.push(nowMs);
          return 3 - quota.length;
        }
      }

      return 3 - Math.min(3, quota.length + 1);
    },

    reset(key: string): void {
      limits.delete(key);
    }
  };
}
