export function createRateLimiter(): RateLimiter {
  const quotas: Map<string, { resetTimeMs: number; uses: number }> = new Map();

  return {
    allow(key: string, nowMs: number): boolean {
      let quota = quotas.get(key);
      if (!quota) {
        quota = { resetTimeMs: nowMs, uses: 0 };
        quotas.set(key, quota);
      }

      updateQuota(quota, nowMs);

      return quota.uses < 3;
    },

    remaining(key: string, nowMs: number): number {
      const quota = quotas.get(key);
      if (!quota) return 3;

      updateQuota(quota, nowMs);

      return Math.max(0, 3 - quota.uses);
    },

    reset(key: string): void {
      const quota = quotas.get(key);
      if (quota) {
        quotas.delete(key);
      }
    }
  };

  function updateQuota(quota: { resetTimeMs: number; uses: number }, nowMs: number) {
    if (nowMs - quota.resetTimeMs >= 1000) {
      quotas.set(key, { resetTimeMs: nowMs, uses: 0 });
    } else {
      ++quota.uses;
    }
  }
}
