export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const windowSize = 1000;
  const maxRequests = 3;
  const state: Map<string, { count: number; windowStart: number }> = new Map();

  return {
    allow(key: string, nowMs: number): boolean {
      const current = state.get(key);

      if (!current) {
        state.set(key, { count: 1, windowStart: nowMs });
        return true;
      }

      if (nowMs - current.windowStart >= windowSize) {
        state.set(key, { count: 1, windowStart: nowMs });
        return true;
      }

      if (current.count < maxRequests) {
        current.count++;
        return true;
      }

      return false;
    },

    reset(key: string): void {
      state.delete(key);
    }
  };
}
