type RateLimitState = {
  count: number;
  windowStart: number | null;
};

type RateLimiter = {
  isAllowed: (key: string, nowMs: number) => boolean;
  reset: (key: string) => void;
  getRemaining: (key: string, nowMs: number) => number;
};

export function createRateLimiter(): RateLimiter {
  const config = {
    maxRequests: 3,
    windowSizeMs: 1000,
  };

  const state: Map<string, RateLimitState> = new Map();

  function isAllowed(key: string, nowMs: number): boolean {
    const currentState = state.get(key);

    if (!currentState) {
      state.set(key, {
        count: 1,
        windowStart: nowMs,
      });
      return true;
    }

    const elapsed = nowMs - currentState.windowStart;

    if (elapsed >= config.windowSizeMs) {
      state.set(key, {
        count: 1,
        windowStart: nowMs,
      });
      return true;
    }

    if (currentState.count < config.maxRequests) {
      currentState.count += 1;
      return true;
    }

    return false;
  }

  function reset(key: string): void {
    state.delete(key);
  }

  function getRemaining(key: string, nowMs: number): number {
    const currentState = state.get(key);

    if (!currentState) {
      return config.maxRequests;
    }

    const elapsed = nowMs - currentState.windowStart;

    if (elapsed >= config.windowSizeMs) {
      return config.maxRequests;
    }

    return Math.max(0, config.maxRequests - currentState.count);
  }

  return {
    isAllowed,
    reset,
    getRemaining,
  };
}
