type Listener<T extends unknown[]> = (...args: T) => unknown;

interface EventEmitter {
  on<T extends unknown[]>(event: string, listener: Listener<T>): void;
  once<T extends unknown[]>(event: string, listener: Listener<T>): void;
  off<T extends unknown[]>(event: string, listener: Listener<T>): void;
  emit<T extends unknown[]>(event: string, ...args: T): unknown[];
}

export function createEventEmitter(): EventEmitter {
  const listeners: Record<string, Listener<unknown[]>[]> = {};

  return {
    on(event, listener) {
      if (!listeners[event]) {
        listeners[event] = [];
      }
      listeners[event].push(listener);
    },

    once(event, listener) {
      const wrapped = (...args: unknown[]) => {
        this.off(event, wrapped);
        return listener(...args);
      };
      this.on(event, wrapped);
    },

    off(event, listener) {
      if (!listeners[event]) {
        return;
      }
      const index = listeners[event].indexOf(listener);
      if (index !== -1) {
        listeners[event].splice(index, 1);
      }
    },

    emit(event, ...args) {
      if (!listeners[event]) {
        return [];
      }
      return listeners[event].map((listener) => listener(...args));
    }
  };
}
