type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

interface Registration {
  listener: Listener
  once: boolean
}

export function createEventEmitter(): EventEmitter {
  const events: Record<string, Registration[]> = {}

  return {
    on(event: string, listener: Listener): number {
      if (!events[event]) {
        events[event] = []
      }
      events[event].push({ listener, once: false })
      return events[event].length
    },

    once(event: string, listener: Listener): number {
      if (!events[event]) {
        events[event] = []
      }
      events[event].push({ listener, once: true })
      return events[event].length
    },

    off(event: string, listener: Listener): boolean {
      if (!events[event]) {
        return false
      }
      const index = events[event].findIndex(r => r.listener === listener)
      if (index === -1) {
        return false
      }
      events[event].splice(index, 1)
      if (events[event].length === 0) {
        delete events[event]
      }
      return true
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!events[event]) {
        return []
      }
      const results: unknown[] = []
      const registrations = [...events[event]]
      for (let i = 0; i < registrations.length; i++) {
        const reg = registrations[i]
        const result = reg.listener(payload)
        results.push(result)
        if (reg.once) {
          const actualIndex = events[event].findIndex(r => r === reg)
          if (actualIndex !== -1) {
            events[event].splice(actualIndex, 1)
            i--
          }
        }
      }
      if (events[event] && events[event].length === 0) {
        delete events[event]
      }
      return results
    },

    listenerCount(event: string): number {
      return events[event] ? events[event].length : 0
    }
  }
}
