export function createRateLimiter() {
  const windowMs = 1000;
  const limit = 3;

  const limiter = {
    lastUseTime: 0,
    windowStart: 0,
    quota: 0,
    keys: new Map<string, { lastUseTime: number; windowStart: number }>(),
  };

  return {
    allow: (key: string, nowMs: number): boolean => {
      if (nowMs - limiter.windowStart >= windowMs) {
        limiter.windowStart = nowMs;
        limiter.quota = limit;
      }
      if (limiter.quota <= 0) {
        return false;
      }
      limiter.quota--;
      limiter.lastUseTime = nowMs;
      return true;
    },
    remaining: (key: string, nowMs: number): number => {
      if (nowMs - limiter.windowStart >= windowMs) {
        limiter.windowStart = nowMs;
        limiter.quota = limit;
      }
      return limiter.quota;
    },
    reset: (key: string) => {
      limiter.keys.set(key, { lastUseTime: nowMs, windowStart: nowMs });
    },
  };
}
