    has(key, nowMs) {
      const entry = map.get(key);
      if (!entry) return false;
      return nowMs < entry.expiresAt;
    },
    delete(key) {
      return map.delete(key);
    },
    size(nowMs) {
      let count = 0;
      for (const entry of map.values()) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear() {
      map.clear();
