interface Listener {
  func: Function;
  once: boolean;
}

function createEventEmitter(): {
  on(event: string, listener: Function, once?: boolean): void;
  off(event: string, listener: Function): void;
  emit(event: string, ...args: any[]): any[];
} {
  const listeners = new Map<string, Listener[]>();

  return {
    on(event: string, listener: Function, once: boolean = false): void {
      if (!listeners.has(event)) {
        listeners.set(event, []);
      }
      listeners.get(event)!.push({ func: listener, once });
    },
    off(event: string, listener: Function): void {
      const eventListeners = listeners.get(event);
      if (!eventListeners) return;
      const index = eventListeners.findIndex(l => l.func === listener);
      if (index !== -1) {
        eventListeners.splice(index, 1);
      }
    },
    emit(event: string, ...args: any[]): any[] {
      const eventListeners = listeners.get(event) || [];
      const results: any[] = [];
      const listenersCopy = [...eventListeners]; // Create a copy to iterate over

      for (const listener of listenersCopy) {
        const result = listener.func(...args);
        results.push(result);
        if (listener.once) {
          const index = eventListeners.findIndex(l => l.func === listener.func);
          if (index !== -1) {
            eventListeners.splice(index, 1);
          }
        }
      }

      return results;
    }
  };
}

export { createEventEmitter };
