export function createEventEmitter() {
  const events = new Map<string, { listeners: Array<{ fn: Function; once: boolean }> }>();

  return {
    emit: (event: string) => {
      const listeners = events.get(event);
      if (!listeners) return [];
      const results: any[] = [];
      for (let i = 0; i < listeners.listeners.length; i++) {
        const listener = listeners.listeners[i];
        const result = listener.fn();
        if (listener.once) {
          listeners.listeners.splice(i, 1);
          i--;
        }
        results.push(result);
      }
      return results;
    },
    on: (event: string, listener: Function, once?: boolean) => {
      if (!events.has(event)) {
        events.set(event, { listeners: [] });
      }
      events.get(event).listeners.push({ fn: listener, once: once ?? false });
    },
    off: (event: string, listener: Function) => {
      const eventListeners = events.get(event);
      if (!eventListeners) return;
      const index = eventListeners.listeners.findIndex(l => l.fn === listener);
      if (index !== -1) {
        eventListeners.listeners.splice(index, 1);
      }
    }
  };
}
