type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  return new EventEmitter();
}

class EventEmitter {
  private eventListeners = new Map<string, { regular: Listener[]; once: Listener[] }>();

  on(event: string, listener: Listener): number {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, { regular: [], once: [] });
    }
    this.eventListeners.get(event)!.regular.push(listener);
    return this.listenerCount(event);
  }

  once(event: string, listener: Listener): number {
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, { regular: [], once: [] });
    }
    this.eventListeners.get(event)!.once.push(listener);
    return this.listenerCount(event);
  }

  off(event: string, listener: Listener): boolean {
    const eventData = this.eventListeners.get(event);
    if (!eventData) return false;

    const regular = eventData.regular;
    const once = eventData.once;

    let removed = false;
    const regularIndex = regular.indexOf(listener);
    if (regularIndex !== -1) {
      regular.splice(regularIndex, 1);
      removed = true;
    } else {
      const onceIndex = once.indexOf(listener);
      if (onceIndex !== -1) {
        once.splice(onceIndex, 1);
        removed = true;
      }
    }

    return removed;
  }

  emit(event: string, payload: unknown): unknown[] {
    const eventData = this.eventListeners.get(event);
    if (!eventData) {
      return [];
    }

    const result: unknown[] = [];
    for (const listener of eventData.regular) {
      result.push(listener(payload));
    }
    for (let i = 0; i < eventData.once.length; i++) {
      const listener = eventData.once[i];
      result.push(listener(payload));
      eventData.once.splice(i, 1);
    }
    return result;
  }

  listenerCount(event: string): number {
    const eventData = this.eventListeners.get(event);
    if (!eventData) {
      return 0;
    }
    return eventData.regular.length + eventData.once.length;
  }
}
