export function createTtlCache() {
  const cache = new Map<string, { value: unknown; expiresAt: number }>;
  return {
    set: (key: string, value: unknown, nowMs: number, ttlMs?: number) => {
      const ttl = ttlMs ?? 1000;
      const expiresAt = nowMs + ttl;
      cache.set(key, { value, expiresAt });
    },
    get: (key: string, nowMs: number) => {
      const entry = cache.get(key);
      if (!entry) return undefined;
      if (nowMs >= entry.expiresAt) return undefined;
      return entry.value;
    },
    has: (key: string, nowMs: number) => {
      const entry = cache.get(key);
      return entry && nowMs < entry.expiresAt;
    },
    delete: (key: string) => {
      const entry = cache.get(key);
      if (entry) {
        cache.delete(key);
        return true;
      }
      return false;
    },
    size: (nowMs: number) => {
      let count = 0;
      for (const [key, entry] of cache) {
        if (nowMs < entry.expiresAt) {
          count++;
        }
      }
      return count;
    },
    clear: () => {
      cache.clear();
    }
  };
}
