export function createEventEmitter() {
  const events = new Map<string, Array<{ listener: Function; isOneTime: boolean }>>();

  return {
    on(event: string, listener: (...args: any[]) => any) {
      if (!events.has(event)) events.set(event, []);
      events.get(event)!.push({ listener, isOneTime: false });
    },
    once(event: string, listener: (...args: any[]) => any) {
      if (!events.has(event)) events.set(event, []);
      events.get(event)!.push({ listener, isOneTime: true });
    },
    off(event: string, listener: (...args: any[]) => any) {
      const listeners = events.get(event);
      if (listeners) {
        const index = listeners.findIndex(
          (e) => e.listener === listener
        );
        if (index !== -1) listeners.splice(index, 1);
      }
    },
    emit(event: string, ...args: any[]) {
      const listeners = events.get(event) || [];
      const results: any[] = [];
      for (const listener of listeners) {
        results.push(listener.listener(...args));
        if (listener.isOneTime) {
          const index = listeners.indexOf(listener);
          if (index !== -1) listeners.splice(index, 1);
        }
      }
      return results;
    }
  };
