type Listener = (payload: unknown) => unknown

interface EventEmitter {
  on(event: string, listener: Listener): number
  once(event: string, listener: Listener): number
  off(event: string, listener: Listener): boolean
  emit(event: string, payload: unknown): unknown[]
  listenerCount(event: string): number
}

export function createEventEmitter(): EventEmitter {
  const eventStore = new Map<string, { regularListeners: Listener[]; oneTimeListeners: Listener[] }>();

  return {
    on(event, listener) {
      if (!eventStore.has(event)) eventStore.set(event, { regularListeners: [], oneTimeListeners: [] });
      eventStore.get(event).regularListeners.push(listener);
      return eventStore.get(event).regularListeners.length;
    },
    once(event, listener) {
      if (!eventStore.has(event)) eventStore.set(event, { regularListeners: [], oneTimeListeners: [] });
      eventStore.get(event).oneTimeListeners.push(listener);
      return eventStore.get(event).regularListeners.length + eventStore.get(event).oneTimeListeners.length;
    },
    off(event, listener) {
      const eventInfo = eventStore.get(event) || { regularListeners: [], oneTimeListeners: [] };
      const indexRegular = eventInfo.regularListeners.indexOf(listener);
      if (indexRegular !== -1) {
        eventInfo.regularListeners.splice(indexRegular, 1);
        return true;
      }
      const indexOneTime = eventInfo.oneTimeListeners.indexOf(listener);
      if (indexOneTime !== -1) {
        eventInfo.oneTimeListeners.splice(indexOneTime, 1);
        return true;
      }
      return false;
    },
    emit(event, payload) {
      const eventInfo = eventStore.get(event) || { regularListeners: [], oneTimeListeners: [] };
      const results = [];

      for (const listener of eventInfo.regularListeners) {
        results.push(listener(payload));
      }

      for (let i = 0; i < eventInfo.oneTimeListeners.length; i++) {
        results.push(eventInfo.oneTimeListeners[i](payload));
        eventInfo.oneTimeListeners.splice(i, 1);
        i++;
      }

      return results;
    },
    listenerCount(event) {
      const eventInfo = eventStore.get(event) || { regularListeners: [], oneTimeListeners: [] };
      return eventInfo.regularListeners.length + eventInfo.oneTimeListeners.length;
    }
  };
}

