export const createRateLimiter = (nowMs: () => number) => {
  const limits = new Map<string, { windowStart: number; count: number }>();

  return {
    allow: (key: string) => {
      const state = limits.get(key) || { windowStart: nowMs(), count: 0 };
      const currentTime = nowMs();
      const windowElapsed = currentTime - state.windowStart >= 1000;

      if (windowElapsed) {
        state.windowStart = currentTime;
        state.count = 1;
      } else {
        if (state.count < 3) {
          state.count++;
        } else {
          return false;
        }
      }
      limits.set(key, state);
      return state.count < 3;
    },
    reset: (key: string) => {
      limits.delete(key);
    }
  };
};
