interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const state = new Map<string, { windowStart: number; count: number }>();

  return {
    allow: (key: string, nowMs: number): boolean => {
      const entry = state.get(key);
      if (!entry) {
        state.set(key, { windowStart: nowMs, count: 0 });
        return true;
      }

      if (nowMs - entry.windowStart >= 1000) {
        state.set(key, { windowStart: nowMs, count: 0 });
      }

      if (entry.count < 3) {
        state.set(key, { windowStart: entry.windowStart, count: entry.count + 1 });
        return true;
      }

      return false;
    },
    remaining: (key: string, nowMs: number): number => {
      const entry = state.get(key);
      if (!entry) {
        return 3;
      }

      if (nowMs - entry.windowStart >= 1000) {
        state.set(key, { windowStart: nowMs, count: 0 });
      }

      return 3 - entry.count;
    },
    reset: (key: string) => {
      state.set(key, { windowStart: Date.now(), count: 0 });
    }
  };
}
