class TtlCacheImpl implements TtlCache {
  private cache = new Map<string, { value: unknown; expiresAt: number }>();

  set(key: string, value: unknown, nowMs: number, ttlMs: number = 1000): void {
    const expiresAt = nowMs + ttlMs;
    this.cache.set(key, { value, expiresAt });
  }

  get(key: string, nowMs: number): unknown {
    const entry = this.cache.get(key);
    if (entry && nowMs < entry.expiresAt) return entry.value;
    return undefined;
  }

  has(key: string, nowMs: number): boolean {
    const entry = this.cache.get(key);
    return entry && nowMs < entry.expiresAt;
  }

  delete(key: string): boolean {
    const entry = this.cache.get(key);
    if (entry) {
      this.cache.delete(key);
      return true;
    }
    return false;
  }

  size(nowMs: number): number {
    return Array.from(this.cache.values()).reduce(
      (count, entry) => count + (entry && nowMs < entry.expiresAt ? 1 : 0),
      0
    );
  }

  clear(): void {
    this.cache.clear();
  }
}

export function createTtlCache(): TtlCache {
  return new TtlCacheImpl();
}

