export function createEventEmitter() {
  const events = new Map<string, Array<{ listener: Function, once: boolean }>>();

  return {
    add(event: string, listener: Function, once = false) {
      if (!events.has(event)) {
        events.set(event, []);
      }
      events.get(event)!.push({ listener, once });
    },
    off(event: string, listener: Function) {
      if (events.has(event)) {
        const listeners = events.get(event)!;
        const index = listeners.findIndex(l => l.listener === listener);
        if (index !== -1) {
          listeners.splice(index, 1);
        }
      }
    },
    emit(event: string, ...args: any[]) {
      if (!events.has(event)) return [];
      const listeners = events.get(event)!;
      const results: any[] = [];
      for (const listener of listeners) {
        const result = listener.listener(...args);
        results.push(result);
        if (listener.once) {
          const index = listeners.findIndex(l => l.listener === listener.listener);
          if (index !== -1) {
            listeners.splice(index, 1);
          }
        }
      }
