export function createRateLimiter() {
  const keyStates: Record<string, number[]> = {};

  return {
    check(key: string, nowMs: number): boolean {
      const arr = keyStates[key] || [];
      const windowStart = nowMs - 1000;
      let left = 0;
      let right = arr.length;
      while (left < right) {
        const mid = Math.floor((left + right) / 2);
        if (arr[mid] >= windowStart) {
          right = mid;
        } else {
          left = mid + 1;
        }
      }
      const count = arr.length - left;
      if (count >= 3) {
        return false;
      }
      arr.push(nowMs);
      return true;
    },
    reset(key: string): void {
      keyStates[key] = [];
    },
  };
}
