export function createEventEmitter() {
  const events = new Map<string, Array<{ handler: Function; once: boolean }>>();

  return {
    on(eventName: string, handler: Function, once = false) {
      if (!events.has(eventName)) {
        events.set(eventName, []);
      }
      events.get(eventName)!.push({ handler, once });
    },
    off(eventName: string, handler: Function) {
      if (events.has(eventName)) {
        events.get(eventName)!.forEach((listener, index) => {
          if (listener.handler === handler) {
            events.get(eventName)!.splice(index, 1);
          }
        });
      }
    },
    emit<T>(eventName: string, ...args: any[]): T[] | undefined {
      if (!events.has(eventName)) return undefined;
      const results: T[] = [];
      const listeners = events.get(eventName)!;
      const newListeners = [];
      for (const listener of listeners) {
        if (listener.handler) {
          const result = listener.handler(...args);
          results.push(result as T);
          if (listener.once) {
            newListeners.push(listener);
          }
        }
      }
      events.get(eventName)!.splice(0, listeners.length, ...newListeners);
      return results;
    }
  };
}
