type Listener = (payload: unknown) => unknown

export function createEventEmitter(): EventEmitter {
  class EventEmitter {
    private listeners = new Map<string, { regular: Listener[], once: Listener[] }>();

    on(event: string, listener: Listener): number {
      if (!this.listeners.has(event)) {
        this.listeners.set(event, { regular: [], once: [] });
      }
      const { regular, once } = this.listeners.get(event) || { regular: [], once: [] };
      regular.push(listener);
      return regular.length;
    }

    once(event: string, listener: Listener): number {
      if (!this.listeners.has(event)) {
        this.listeners.set(event, { regular: [], once: [] });
      }
      const { regular, once } = this.listeners.get(event) || { regular: [], once: [] };
      once.push(listener);
      return once.length;
    }

    off(event: string, listener: Listener): boolean {
      if (!this.listeners.has(event)) {
        return false;
      }
      const { regular, once } = this.listeners.get(event) || { regular: [], once: [] };
      const regularIndex = regular.indexOf(listener);
      if (regularIndex !== -1) {
        regular.splice(regularIndex, 1);
        return true;
      }
      const onceIndex = once.indexOf(listener);
      if (onceIndex !== -1) {
        once.splice(onceIndex, 1);
        return true;
      }
      return false;
    }

    emit(event: string, payload: unknown): unknown[] {
      if (!this.listeners.has(event)) {
        return [];
      }
      const { regular, once } = this.listeners.get(event) || { regular: [], once: [] };
      const results: unknown[] = [];

      for (const listener of regular) {
        results.push(listener(payload));
      }

      for (let i = once.length - 1; i >= 0; i--) {
        const listener = once[i];
        results.push(listener(payload));
        once.splice(i, 1);
      }

      return results;
    }

    listenerCount(event: string): number {
      if (!this.listeners.has(event)) {
        return 0;
      }
      const { regular, once } = this.listeners.get(event) || { regular: [], once: [] };
      return regular.length + once.length;
    }
  }

  return new EventEmitter();
}
