export function createTtlCache(): {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
} {
  const entries = new Map<string, { value: unknown; expiresAt: number }>();

  return {
    set(key, value, nowMs, ttlMs = 1000) {
      const expiresAt = nowMs + ttlMs;
      entries.set(key, { value, expiresAt });
    },
    get(key, nowMs) {
      const entry = entries.get(key);
      return entry?.expiresAt > nowMs ? entry.value : undefined;
    },
    has(key, nowMs) {
      const entry = entries.get(key);
      return !!entry && entry.expiresAt > nowMs;
    },
    delete(key) {
      const entry = entries.get(key);
      if (entry) {
        entries.delete(key);
        return true;
      }
      return false;
    },
    size(nowMs) {
      let count = 0;
      for (const [_, entry] of entries.entries()) {
        if (entry.expiresAt > nowMs) count++;
      }
      return count;
    },
    clear() {
      entries.clear();
    }
  };
}
