export function createTtlCache(): TtlCache {
  return new TtlCacheImpl();
}

interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void
  get(key: string, nowMs: number): unknown
  has(key: string, nowMs: number): boolean
  delete(key: string): boolean
  size(nowMs: number): number
  clear(): void
}

class TtlCacheImpl implements TtlCache {
  private cache = new Map<string, { value: unknown; expiresAt: number }>();

  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
    const expiration = nowMs + (ttlMs ?? 1000);
    this.cache.set(key, { value, expiresAt: expiration });
  }

  get(key: string, nowMs: number): unknown {
    const entry = this.cache.get(key);
    if (entry && entry.expiresAt > nowMs) {
      return entry.value;
    }
    return undefined;
  }

  has(key: string, nowMs: number): boolean {
    const entry = this.cache.get(key);
    return !!entry && entry.expiresAt > nowMs;
  }

  delete(key: string): boolean {
    const entry = this.cache.get(key);
    if (entry) {
      this.cache.delete(key);
      return true;
    }
    return false;
  }

  size(nowMs: number): number {
    let count = 0;
    for (const entry of this.cache.values()) {
      if (entry.expiresAt > nowMs) {
        count++;
      }
    }
    return count;
  }

  clear(): void {
    this.cache.clear();
  }
}
