        const now = Date.now() + nowMs;
        let value = cache[key];
        if (value && value.expiresAt) {
          if (now < value.expiresAt) {
            return value;
          }
        }
      }
      undefined;
    },

    has(key: string, nowMs: number): boolean {
      if (cache && key in cache) {
        const now = Date.now() + nowMs;
        let value = cache[key];
        if (value && value.expiresAt) {
          if (now >= value.expiresAt) {
            return false;
          }
        }
