        delete cache[key];
        return true;
      }
      false;
    },

    size(nowMs: number): number {
      if (cache) {
        return Object.keys(cache).length;
      }
      return 0;
    },

    clear(): void {
      if (cache) {
        Object.keys(cache).forEach(k => delete cache[k]);
      }
    }
  };
