      if (!entry) return undefined
      if (nowMs >= entry.expiresAt) {
        store.delete(key)
        return undefined
      }
      return entry.value
    },
    has(key, nowMs) {
      const entry = store.get(key)
      if (!entry) return false
      if (nowMs >= entry.expiresAt) {
        store.delete(key)
        return false
      }
      return true
    },
    delete(key) {
      return store.delete(key)
    },
    size(nowMs) {
      let count = 0
      for (const entry of store.values()) {
        if (nowMs < entry.expiresAt) {
          count++
        }
      }
      return count
    },
    clear() {
      store.clear()
    }
  }
