type Todo = {
  id: number
  text: string
  completed: boolean
}

type TodoApp = {
  addTodo(text: string): Todo
  getTodo(id: number): Todo | undefined
  toggleTodo(id: number): void
  deleteTodo(id: number): boolean
  listTodos(): Todo[]
  listCompleted(): Todo[]
  listPending(): Todo[]
  clearCompleted(): void
}

export function createTodoApp(): TodoApp {
  let nextId = 1
  const todos: Todo[] = []

  return {
    addTodo(text: string): Todo {
      const todo: Todo = {
        id: nextId++,
        text,
        completed: false
      }
      todos.push(todo)
      return todo
    },

    getTodo(id: number): Todo | undefined {
      return todos.find(t => t.id === id)
    },

    toggleTodo(id: number): void {
      const todo = todos.find(t => t.id === id)
      if (todo !== undefined) {
        todo.completed = !todo.completed
      }
    },

    deleteTodo(id: number): boolean {
      const index = todos.findIndex(t => t.id === id)
      if (index === -1) {
        return false
      }
      todos.splice(index, 1)
      return true
    },

    listTodos(): Todo[] {
      return [...todos]
    },

    listCompleted(): Todo[] {
      return todos.filter(t => t.completed)
    },

    listPending(): Todo[] {
      return todos.filter(t => !t.completed)
    },

    clearCompleted(): void {
      const pending = todos.filter(t => !t.completed)
      todos.length = 0
      pending.forEach(t => todos.push(t))
    }
  }
}
