export function createCalculator(): Calculator {
  return {
    add(n: number): Calculator {
      const calculator = {
        history: [calculator.history || 0, calculator.currentValue + n],
        currentValue: calculator.currentValue + n,
        memory: calculator.memory,
        operations: operations
      };
      return { ...calculator, operations: [] };
    },
    subtract(n: number): Calculator {
      const history = Array.isArray(calculator.history) ? [...calculator.history] : [];
      history.push(calculator.currentValue - n);
      return {
        currentValue: calculator.currentValue - n,
        memory: calculator.memory,
        operations: operations
      };
    },
    multiply(n: number): Calculator {
      const history = Array.isArray(calculator.history) ? [...calculator.history] : [];
      history.push(calculator.currentValue * n);
      return {
        currentValue: calculator.currentValue * n,
        memory: calculator.memory,
        operations: operations
      };
    },
    divide(n: number): Calculator {
      if (n === 0) return null;
      const history = Array.isArray(calculator.history) ? [...calculator.history] : [];
      history.push(calculator.currentValue / n);
      return {
        currentValue: calculator.currentValue / n,
        memory: calculator.memory,
        operations: operations
      };
    },
    clear(): Calculator {
      return {
        currentValue: 0,
        history: [],
        memory: 0,
        operations: []
      };
    },
    result(): number {
      return this.currentValue;
    },
    memoryStore(): Calculator {
      const memory = Array.isArray(this.memory) ? [...this.memory] : [];
      return {
        currentValue: this.currentValue,
        history: this.history,
        memory: [...this.memory, this.currentValue],
        operations: []
      };
    },
    memoryRecall(): number {
      return this.memory[0] ?? 0;
    },
    memoryClear(): Calculator {
      return {
        currentValue: this.currentValue,
        history: this.history,
        memory: 0,
        operations: []
      };
    },
    memoryAdd(): Calculator {
      const memory = Array.isArray(this.memory) ? [...this.memory] : [];
      const currentValue = this.currentValue;
      return {
        currentValue: currentValue,
        history: this.history,
        memory: [...memory, currentValue],
        operations: operations
      };
    }
  }
}
