export function createTodoApp(): {
  addTodo(text: string): { id: number, text: string, completed: boolean };
  getTodo(id: number): { id: number, text: string, completed: boolean } | undefined;
  toggleTodo(id: number): void;
  deleteTodo(id: number): boolean;
  listTodos(): Array<{ id: number, text: string, completed: boolean }>;
  listCompleted(): Array<{ id: number, text: string, completed: boolean }>;
  listPending(): Array<{ id: number, text: string, completed: boolean }>;
  clearCompleted(): void;
} {
  let nextId = 1;

  const todos: { id: number, text: string, completed: boolean }[] = [];

  const addTodo = (text: string): { id: number, text: string, completed: boolean } => {
    const todo: { id: number, text: string, completed: boolean } = {
      id: nextId++,
      text,
      completed: false
    };
    todos.push(todo);
    return todo;
  };

  const getTodo = (id: number): { id: number, text: string, completed: boolean } | undefined => {
    const todo = todos.find(todo => todo.id === id);
    return todo;
  };

  const toggleTodo = (id: number) => {
    for (const todo of todos) {
      if (todo.id === id) {
        todo.completed = !todo.completed;
        return;
      }
    }
  };

  const deleteTodo = (id: number): boolean => {
    const index = todos.findIndex(todo => todo.id === id);
    if (index === -1) return false;
    todos.splice(index, 1);
    return true;
  };

  const listTodos = (): Array<{ id: number, text: string, completed: boolean }> => {
    return todos;
  };

  const listCompleted = (): Array<{ id: number, text: string, completed: boolean }> => {
    return todos.filter(todo => todo.completed);
  };

  const listPending = (): Array<{ id: number, text: string, completed: boolean }> => {
    return todos.filter(todo => !todo.completed);
  };

  const clearCompleted = () => {
    const completedIndices = todos
      .map((todo, index) => todo.completed ? index : -1)
      .filter(index => index !== -1);
    if (completedIndices.length === 0) return;
    todos.splice(...completedIndices, 1);
  };
}
