createTtlCache = (() => {
  const Map = {
    get: Object.Getprototypeof<unknown, (key: string, nowMs: number) => unknown>['Map']['get'],
    has: Object.Getprototypeof<unknown>['Map']['has'],
    set: Object.Getprototypeof<unknown>['Map']['set'],
    delete: Object.Getprototypeof<unknown>['Map']['delete'],
    size: Object.Getprototypeof<unknown>['Map']['size'],
    clear: Object.Getprototypeof<unknown>['Map']['clear']
  } as typeof Map

  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void | undefined {
      const expiresAt = ttlMs ? nowMs + ttlMs : nowMs + 1000
      const entry = new (Map as any)().set(value, expiresAt)
      Map.set.call(Map, key, entry)
    },
    get(key: string, nowMs: number): unknown | undefined {
      const entry = (Map as any).get(key, nowMs)
      const entryTime = entry[1]
      return nowMs >= entryTime ? undefined : entry
    },
    has(key: string, nowMs: number): boolean {
      const entry = (Map as any).has(key, nowMs)
      const entryTime = entry
      if (!entryTime) return false
      return nowMs >= entryTime
    },
    delete(key: string): boolean {
      if (this.has(key, nowMs)) {
        (Map as any).delete(key, nowMs)
        return true
      }
      return false
    },
    size(nowMs: number): number {
      const entryMap = (Map as any)
