  add: (n: number) => Calculator;
  subtract: (n: number) => Calculator;
  multiply: (n: number) => Calculator;
  divide: (n: number) => Calculator;
  clear: () => Calculator;
  result: () => number;
  memoryStore: () => Calculator;
  memoryAdd: () => Calculator;
  memoryRecall: () => number;
}

export function createCalculator(): Calculator {
  let currentValue: number = 0;
  let memoryValue: number = 0;

  const calculator: Calculator = {
    add: (n: number) => {
      currentValue += n;
      return calculator;
    },
    subtract: (n: number) => {
      currentValue -= n;
      return calculator;
    },
    multiply: (n: number) => {
      currentValue *= n;
      return calculator;
    },
    divide: (n: number) => {
      currentValue /= n;
      return calculator;
    },
    clear: () => {
      currentValue = 0;
      return calculator;
    },
    result: () => {
      return currentValue;
    },
    memoryStore: () => {
      memoryValue = currentValue;
      return calculator;
    },
    memoryAdd: () => {
      memoryValue += currentValue;
      return calculator;
    },
    memoryRecall: () => {
      return memoryValue;
    },
  };

  return calculator;
}
