    },
    clear: function(): Calculator {
      this.currentVal = 0;
      return this;
    },
    result: function(): number {
      return this.currentVal;
    },
    memoryStore: function(): Calculator {
      this.memory = this.currentVal;
      return this;
    },
    memoryRecall: function(): number {
      return this.memory;
