const createEventEmitter = (): {
  on: (eventName: string, listener: (...args: any[]) => any) => void;
  once: (eventName: string, listener: (...args: any[]) => any) => void;
  off: (eventName: string, listener: (...args: any[]) => any) => void;
  emit: (eventName: string, ...args: any[]) => any[];
} => {
  const events = new Map<string, { listeners: { fn: (...args: any[]) => any; isOnce: boolean }[] }>();

  const on = (eventName: string, listener: (...args: any[]) => any) => {
    if (!events.has(eventName)) {
      events.set(eventName, { listeners: [] });
    }
    const event = events.get(eventName)!;
    event.listeners.push({ fn: listener, isOnce: false });
  };

  const once = (eventName: string, listener: (...args: any[]) => any) => {
    on(eventName, listener);
  };

  const off = (eventName: string, listener: (...args: any[]) => any) => {
    const event = events.get(eventName);
    if (!event) return;
    for (let i = event.listeners.length - 1; i >= 0; i--) {
      if (event.listeners[i].fn === listener) {
        event.listeners.splice(i, 1);
        return;
      }
    }
  };

  const emit = (eventName: string, ...args: any[]) => {
    const event = events.get(eventName);
    if (!event || event.listeners.length === 0) return [];

    const listeners = event.listeners;
    const results: any[] = [];

    for (let i = 0; i < listeners.length; i++) {
      try {
        results.push(listeners[i].fn(...args));
      } catch (e) {
        // Ignore errors to match standard emitter behavior unless specified otherwise
        // Requirement does not specify error handling
      }
    }

    // Remove one-time listeners after execution
    for (let i = listeners.length - 1; i >= 0; i--) {
      if (listeners[i].isOnce) {
        listeners.splice(i, 1);
      }
    }

    return results;
  };

  return { on, once, off, emit };
};

export const createEventEmitter = createEventEmitter;
