type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const events: Map<string, { onListeners: Listener[]; onceListeners: Listener[] }> = new Map();

  const on = (event: string, listener: Listener): number => {
    if (!events.has(event)) {
      events.set(event, { onListeners: [], onceListeners: [] });
    }
    const { onListeners, onceListeners } = events.get(event)!;
    onListeners.push(listener);
    return onListeners.length + onceListeners.length;
  };

  const once = (event: string, listener: Listener): number => {
    if (!events.has(event)) {
      events.set(event, { onListeners: [], onceListeners: [] });
    }
    const { onListeners, onceListeners } = events.get(event)!;
    onceListeners.push(listener);
    return onListeners.length + onceListeners.length;
  };

  const off = (event: string, listener: Listener): boolean => {
    const eventObj = events.get(event);
    if (!eventObj) return false;
    const { onListeners, onceListeners } = eventObj;
    let found = false;
    const onIndex = onListeners.indexOf(listener);
    if (onIndex !== -1) {
      onListeners.splice(onIndex, 1);
      found = true;
    } else {
      const onceIndex = onceListeners.indexOf(listener);
      if (onceIndex !== -1) {
        onceListeners.splice(onceIndex, 1);
        found = true;
      }
    }
    return found;
  };

  const emit = (event: string, payload: unknown): unknown[] => {
    const eventObj = events.get(event);
    if (!eventObj) return [];
    const { onListeners, onceListeners } = eventObj;
    const results: unknown[] = [];
    for (const l of onListeners) {
      results.push(l(payload));
    }
    for (const l of onceListeners) {
      results.push(l(payload));
    }
    events.set(event, { onListeners, onceListeners: [] });
    return results;
  };

  const listenerCount = (event: string): number => {
    const eventObj = events.get(event);
    if (!eventObj) return 0;
    return eventObj.onListeners.length + eventObj.onceListeners.length;
  };

  return { on, once, off, emit, listenerCount };
}
