  getTodo(id: number): Todo | undefined
  toggleTodo(id: number): void
  deleteTodo(id: number): boolean
  listTodos(): Todo[]
  listCompleted(): Todo[]
  listPending(): Todo[]
  clearCompleted(): void
}

export function createTodoApp(): TodoApp {
  let todos: Todo[] = []
  let nextId: number = 1

  return {
    addTodo: (text: string): Todo => {
      const newTodo: Todo = {
        id: nextId++,
        text,
        completed: false
      }
      todos.push(newTodo)
      return newTodo
    },
    getTodo: (id: number): Todo | undefined => {
      const index = todos.findIndex(t => t.id === id)
      if (index !== -1) {
        return todos[index]
      }
      return undefined
    },
    toggleTodo: (id: number): void => {
      const index = todos.findIndex(t => t.id === id)
      if (index !== -1) {
        todos[index].completed = !todos[index].completed
      }
    },
    deleteTodo: (id: number): boolean => {
      const index = todos.findIndex(t => t.id === id)
      if (index !== -1) {
        todos.splice(index, 1)
        return true
      }
      return false
    },
    listTodos: (): Todo[] => {
      return [...todos]
    },
    listCompleted: (): Todo[] => {
      return todos.filter(t => t.completed)
    },
    listPending: (): Todo[] => {
      return todos.filter(t => !t.completed)
    },
    clearCompleted: (): void => {
      const remaining = todos.filter(t => !t.completed)
      todos = [...remaining]
    }
  }
}
