    addTodo(text: string): Todo {
      const id = todoIdCounter++;
      todos[id] = { id, text, completed: false };
      return todos[id];
    },

    getTodo(id: number): Todo | undefined {
      return todos[id];
    },

    toggleTodo(id: number): void {
      const todo = todos[id];
      if (todo) {
        todo.completed = !todo.completed;
      }
    },

    deleteTodo(id: number): boolean {
      if (id in todos) {
        delete todos[id];
        return true;
      }
      return false;
    },

    listTodos(): Todo[] {
      return Object.values(todos);
    },

    listCompleted(): Todo[] {
      const completed: Todo[] = [];
      Object.values(todos).forEach((todo) => {
        if (todo.completed) {
          completed.push(todo);
        }
      });
      return completed;
    },

    listPending(): Todo[] {
      const pending: Todo[] = [];
      Object.values(todos).forEach((todo) => {
        if (!todo.completed) {
          pending.push(todo);
        }
      });
      return pending;
    },

    clearCompleted(): void {
      const completed = Object.keys(todos).filter((id) => todos[id as number].completed);
      completed.forEach((id) => {
        delete todos[id];
      });
    },
  };
