const createCalculator = (): Calculator => {
  let currentValue: number = 0;
  let memory: number = 0;

  const calculator: Calculator = {
    add(n: number): Calculator {
      currentValue += n;
      return calculator;
    },
    subtract(n: number): Calculator {
      currentValue -= n;
      return calculator;
    },
    multiply(n: number): Calculator {
      currentValue *= n;
      return calculator;
    },
    divide(n: number): Calculator {
      currentValue /= n;
      return calculator;
    },
    clear(): Calculator {
      currentValue = 0;
      return calculator;
    },
    result(): number {
      return currentValue;
    },
    memoryStore(): Calculator {
      memory = currentValue;
      return calculator;
    },
    memoryRecall(): number {
      return memory;
    },
    memoryClear(): Calculator {
      memory = 0;
      return calculator;
    },
    memoryAdd(): Calculator {
      memory += currentValue;
      return calculator;
    },
  };

  return calculator;
};

