export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const windows = new Map<string, { start: number; count: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const windowInfo = windows.get(key) || { start: nowMs, count: 0 };
      const elapsed = nowMs - windowInfo.start;

      if (elapsed >= windowMs) {
        windowInfo.start = nowMs;
        windowInfo.count = 0;
      }

      if (windowInfo.count < limit) {
        windowInfo.count += 1;
        windows.set(key, windowInfo);
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const windowInfo = windows.get(key) || { start: nowMs, count: 0 };
      const elapsed = nowMs - windowInfo.start;

      if (elapsed >= windowMs) {
        return limit;
      }

      return Math.max(0, limit - windowInfo.count);
    },

    reset(key: string): void {
      windows.delete(key);
    },
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
