    size(nowMs: number): number {
      const keys = Array.from(store.keys());
      for (const key of keys) {
        const entry = store.get(key)!;
        if (nowMs >= entry.expiresAt) {
          store.delete(key);
        }
      }
      return store.size;
    },

    clear(): void {
