export function createEventEmitter(): EventEmitter {
  const listenersMap = new Map<string, Listener[]>();

  return {
    on(event: string, listener: Listener): number {
      if (!listenersMap.has(event)) {
        listenersMap.set(event, []);
      }
      listenersMap.get(event)!.push(listener);
      return this.listenerCount(event);
    },

    once(event: string, listener: Listener): number {
      const wrappedListener = (...args: unknown[]) => {
        listener(...args);
        this.off(event, wrappedListener);
      };
      return this.on(event, wrappedListener);
    },

    off(event: string, listener: Listener): boolean {
      if (!listenersMap.has(event)) return false;
      const idx = listenersMap.get(event)!.findIndex(l => l === listener);
      if (idx === -1) return false;
      listenersMap.get(event)!.splice(idx, 1);
      return true;
    },

    emit(event: string, payload: unknown): unknown[] {
      if (!listenersMap.has(event)) return [];
      const listeners = [...listenersMap.get(event)!];
      return listeners.map(fn => fn(payload));
    },

    listenerCount(event: string): number {
      return listenersMap.get(event)?.length ?? 0;
    }
  };
}

type Listener = (payload: unknown) => unknown;

interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}
