export function createRateLimiter(): RateLimiter {
  const state = new Map<string, { count: number; windowStart: number }>();

  return {
    allow(key: string, nowMs: number): boolean {
      const entry = state.get(key);
      const now = nowMs;
      const limit = 3;
      const windowMs = 1000;

      if (!entry || now - entry.windowStart >= windowMs) {
        state.set(key, { count: 0, windowStart: now });
        state.get(key).count += 1;
        return true;
      }

      if (entry.count < limit) {
        entry.count += 1;
        return true;
      }

      return false;
    },

    remaining(key: string, nowMs: number): number {
      const entry = state.get(key);
      if (!entry) return 0;
      return Math.max(0, entry.count < 3 ? 3 - entry.count : 0);
    },

    reset(key: string): void {
      state.delete(key);
    },
  };
}

interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}
