export function createRateLimiter() {
    const LIMIT = 3;
    const WINDOW_MS = 1000;

    const stateMap = new Map<string, { count: number; start: number }>();

    const limiter = (key: string, nowMs: number): boolean => {
        let record = stateMap.get(key);
        if (!record) {
            record = { count: 0, start: nowMs };
            stateMap.set(key, record);
        }

        if (nowMs - record.start >= WINDOW_MS) {
            // Window has elapsed; start a fresh window
            record.count = 0;
            record.start = nowMs;
        }

        if (record.count < LIMIT) {
            record.count++;
            return true;
        }
        return false;
    };

    // Attach reset method to the returned function
    (limiter as any).reset = (key: string): void => {
        stateMap.delete(key);
    };

    return limiter;
}
