        const arr = listenersMap.get(event) ?? [];
        arr.push({ fn, once: true });
        listenersMap.set(event, arr);
    }

    function off(event: string, fn: Listener): void {
        const arr = listenersMap.get(event);
        if (!arr) return;
        for (let i = 0; i < arr.length; i++) {
            if (arr[i].fn === fn) {
                arr.splice(i, 1);
                break;
            }
        }
        if (arr.length === 0) {
            listenersMap.delete(event);
        }
    }

    function emit(event: string, ...args: any[]): any[] {
        const arr = listenersMap.get(event);
        if (!arr) return [];
        const results: any[] = [];
        for (const entry of [...arr]) {
            const result = entry.fn(...args);
            results.push(result);
            if (entry.once) {
