      return listeners.get(event)!.once.length + listeners.get(event)!.on.length;
    },
    once(event: string, listener: Listener): number {
      if (!listeners.has(event)) {
        listeners.set(event, { on: [], once: [] });
      }
      listeners.get(event)!.once.push(listener);
      return listeners.get(event)!.once.length + listeners.get(event)!.on.length;
    },
    off(event: string, listener: Listener): boolean {
      const entry = listeners.get(event);
      if (!entry) return false;
      for (let i = 0; i < entry.on.length; i++) {
        if (entry.on[i] === listener) {
          entry.on.splice(i, 1);
          return true;
        }
      }
      for (let i = 0; i < entry.once.length; i++) {
        if (entry.once[i] === listener) {
          entry.once.splice(i, 1);
          return true;
        }
      }
      return false;
    },
    emit(event: string, payload: unknown): unknown[] {
      const entry = listeners.get(event);
      if (!entry) return [];
      const results: unknown[] = [];
      for (const fn of entry.on) {
        results.push(fn(payload));
      }
      for (const fn of entry.once) {
        results.push(fn(payload));
      }
      listeners.set(event, { ...entry, once: [] });
      return results;
    },
    listenerCount(event: string): number {
      const entry = listeners.get(event);
      if (!entry) return 0;
      return entry.on.length + entry.once.length;
    },
  };
