export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const store = new Map<string, { count: number; start: number }>();
  return {
    allow(key: string, nowMs: number): boolean {
      let entry = store.get(key);
      if (!entry) {
        entry = { count: 0, start: nowMs };
        store.set(key, entry);
      }
      if (nowMs - entry.start >= windowMs) {
        entry.count = 0;
        entry.start = nowMs;
      }
      if (entry.count < limit) {
        entry.count++;
        return true;
      }
      return false;
    },
    remaining(key: string, nowMs: number): number {
      let entry = store.get(key);
      if (!entry) {
        return limit;
      }
      if (nowMs - entry.start >= windowMs) {
        entry.count = 0;
        entry.start = nowMs;
      }
      const r = limit - entry.count;
      return r > 0 ? r : 0;
    },
    reset(key: string): void {
      store.delete(key);
    },
  };
}

