export function createTtlCache(): TtlCache {
  const DEFAULT_TTL = 1000;
  const entries = new Map<string, { value: unknown, expiresAt: number }>();
  return {
    set(key: string, value: unknown, nowMs: number, ttlMs?: number): void {
      const ttl = typeof ttlMs === 'number' ? ttlMs : DEFAULT_TTL;
      entries.set(key, { value, expiresAt: nowMs + ttl });
    },
    get(key: string, nowMs: number): unknown {
      const entry = entries.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        if (entry && nowMs >= entry.expiresAt) entries.delete(key);
        return undefined;
      }
      return entry.value;
    },
    has(key: string, nowMs: number): boolean {
      const entry = entries.get(key);
      if (!entry || nowMs >= entry.expiresAt) {
        if (entry && nowMs >= entry.expiresAt) entries.delete(key);
        return false;
      }
      return true;
    },
    delete(key: string): boolean {
      return entries.delete(key);
    },
    size(nowMs: number): number {
      let count = 0;
      for (const [k, e] of entries) {
        if (nowMs < e.expiresAt) {
          count++;
        } else {
          entries.delete(k);
        }
      }
      return count;
    },
    clear(): void {
      entries.clear();
    },
  };
}

interface TtlCache {
